export const MIGRATIONS: {name:string; sql:string}[] = [
  { name: "20251224115244_a8cf95a7-1f7b-4e4a-bf37-cf0d3fa4141a.sql", sql: "-- Create profiles table\nCREATE TABLE public.profiles (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE,\n  full_name TEXT,\n  avatar_url TEXT,\n  study_goal TEXT DEFAULT 'general',\n  daily_study_minutes INTEGER DEFAULT 30,\n  preferred_study_time TEXT DEFAULT 'morning',\n  notification_enabled BOOLEAN DEFAULT true,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- Enable RLS\nALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;\n\n-- RLS Policies\nCREATE POLICY \"Users can view their own profile\"\nON public.profiles FOR SELECT\nUSING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can insert their own profile\"\nON public.profiles FOR INSERT\nWITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update their own profile\"\nON public.profiles FOR UPDATE\nUSING (auth.uid() = user_id);\n\n-- Function to update timestamps\nCREATE OR REPLACE FUNCTION public.update_updated_at_column()\nRETURNS TRIGGER AS $$\nBEGIN\n  NEW.updated_at = now();\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SET search_path = public;\n\n-- Trigger for timestamp updates\nCREATE TRIGGER update_profiles_updated_at\nBEFORE UPDATE ON public.profiles\nFOR EACH ROW\nEXECUTE FUNCTION public.update_updated_at_column();\n\n-- Function to create profile on signup\nCREATE OR REPLACE FUNCTION public.handle_new_user()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nSECURITY DEFINER SET search_path = public\nAS $$\nBEGIN\n  INSERT INTO public.profiles (user_id, full_name)\n  VALUES (NEW.id, NEW.raw_user_meta_data ->> 'full_name');\n  RETURN NEW;\nEND;\n$$;\n\n-- Trigger to auto-create profile on user signup\nCREATE TRIGGER on_auth_user_created\nAFTER INSERT ON auth.users\nFOR EACH ROW EXECUTE FUNCTION public.handle_new_user();" },
  { name: "20251224120318_32291845-c831-413d-8e61-c4d4e120445a.sql", sql: "-- Create app role enum\nCREATE TYPE public.app_role AS ENUM ('admin', 'moderator', 'user');\n\n-- Create user_roles table\nCREATE TABLE public.user_roles (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL,\n  role app_role NOT NULL DEFAULT 'user',\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  UNIQUE (user_id, role)\n);\n\nALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;\n\n-- Security definer function to check roles\nCREATE OR REPLACE FUNCTION public.has_role(_user_id UUID, _role app_role)\nRETURNS BOOLEAN\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1\n    FROM public.user_roles\n    WHERE user_id = _user_id\n      AND role = _role\n  )\n$$;\n\nCREATE POLICY \"Users can view their own roles\"\nON public.user_roles FOR SELECT\nUSING (auth.uid() = user_id);\n\n-- Create folders table\nCREATE TABLE public.folders (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  name TEXT NOT NULL,\n  color TEXT DEFAULT '#6366f1',\n  parent_id UUID REFERENCES public.folders(id) ON DELETE SET NULL,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.folders ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Users can view their own folders\"\nON public.folders FOR SELECT USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can create their own folders\"\nON public.folders FOR INSERT WITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update their own folders\"\nON public.folders FOR UPDATE USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can delete their own folders\"\nON public.folders FOR DELETE USING (auth.uid() = user_id);\n\nCREATE TRIGGER update_folders_updated_at BEFORE UPDATE ON public.folders\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\n-- Create notes table\nCREATE TABLE public.notes (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  folder_id UUID REFERENCES public.folders(id) ON DELETE SET NULL,\n  title TEXT NOT NULL,\n  content TEXT,\n  is_public BOOLEAN DEFAULT false,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.notes ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Users can view their own notes\"\nON public.notes FOR SELECT USING (auth.uid() = user_id OR is_public = true);\n\nCREATE POLICY \"Users can create their own notes\"\nON public.notes FOR INSERT WITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update their own notes\"\nON public.notes FOR UPDATE USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can delete their own notes\"\nON public.notes FOR DELETE USING (auth.uid() = user_id);\n\nCREATE TRIGGER update_notes_updated_at BEFORE UPDATE ON public.notes\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\n-- Create tags table\nCREATE TABLE public.tags (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  name TEXT NOT NULL,\n  color TEXT DEFAULT '#6366f1',\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  UNIQUE(user_id, name)\n);\n\nALTER TABLE public.tags ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Users can view their own tags\"\nON public.tags FOR SELECT USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can create their own tags\"\nON public.tags FOR INSERT WITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update their own tags\"\nON public.tags FOR UPDATE USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can delete their own tags\"\nON public.tags FOR DELETE USING (auth.uid() = user_id);\n\n-- Create note_tags junction table\nCREATE TABLE public.note_tags (\n  note_id UUID NOT NULL REFERENCES public.notes(id) ON DELETE CASCADE,\n  tag_id UUID NOT NULL REFERENCES public.tags(id) ON DELETE CASCADE,\n  PRIMARY KEY (note_id, tag_id)\n);\n\nALTER TABLE public.note_tags ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Users can view note_tags for their notes\"\nON public.note_tags FOR SELECT\nUSING (EXISTS (SELECT 1 FROM public.notes WHERE id = note_id AND user_id = auth.uid()));\n\nCREATE POLICY \"Users can create note_tags for their notes\"\nON public.note_tags FOR INSERT\nWITH CHECK (EXISTS (SELECT 1 FROM public.notes WHERE id = note_id AND user_id = auth.uid()));\n\nCREATE POLICY \"Users can delete note_tags for their notes\"\nON public.note_tags FOR DELETE\nUSING (EXISTS (SELECT 1 FROM public.notes WHERE id = note_id AND user_id = auth.uid()));\n\n-- Create flashcard_decks table\nCREATE TABLE public.flashcard_decks (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  note_id UUID REFERENCES public.notes(id) ON DELETE SET NULL,\n  name TEXT NOT NULL,\n  description TEXT,\n  subject TEXT,\n  is_public BOOLEAN DEFAULT false,\n  card_count INTEGER DEFAULT 0,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.flashcard_decks ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Users can view their own decks or public decks\"\nON public.flashcard_decks FOR SELECT USING (auth.uid() = user_id OR is_public = true);\n\nCREATE POLICY \"Users can create their own decks\"\nON public.flashcard_decks FOR INSERT WITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update their own decks\"\nON public.flashcard_decks FOR UPDATE USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can delete their own decks\"\nON public.flashcard_decks FOR DELETE USING (auth.uid() = user_id);\n\nCREATE TRIGGER update_flashcard_decks_updated_at BEFORE UPDATE ON public.flashcard_decks\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\n-- Create flashcards table with spaced repetition\nCREATE TABLE public.flashcards (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  deck_id UUID NOT NULL REFERENCES public.flashcard_decks(id) ON DELETE CASCADE,\n  front TEXT NOT NULL,\n  back TEXT NOT NULL,\n  hint TEXT,\n  next_review TIMESTAMP WITH TIME ZONE DEFAULT now(),\n  ease_factor NUMERIC(4,2) DEFAULT 2.5,\n  interval_days INTEGER DEFAULT 0,\n  repetitions INTEGER DEFAULT 0,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.flashcards ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Users can view flashcards in their decks\"\nON public.flashcards FOR SELECT\nUSING (EXISTS (SELECT 1 FROM public.flashcard_decks WHERE id = deck_id AND (user_id = auth.uid() OR is_public = true)));\n\nCREATE POLICY \"Users can create flashcards in their decks\"\nON public.flashcards FOR INSERT\nWITH CHECK (EXISTS (SELECT 1 FROM public.flashcard_decks WHERE id = deck_id AND user_id = auth.uid()));\n\nCREATE POLICY \"Users can update flashcards in their decks\"\nON public.flashcards FOR UPDATE\nUSING (EXISTS (SELECT 1 FROM public.flashcard_decks WHERE id = deck_id AND user_id = auth.uid()));\n\nCREATE POLICY \"Users can delete flashcards in their decks\"\nON public.flashcards FOR DELETE\nUSING (EXISTS (SELECT 1 FROM public.flashcard_decks WHERE id = deck_id AND user_id = auth.uid()));\n\nCREATE TRIGGER update_flashcards_updated_at BEFORE UPDATE ON public.flashcards\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\n-- Function to update deck card count\nCREATE OR REPLACE FUNCTION public.update_deck_card_count()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF TG_OP = 'INSERT' THEN\n    UPDATE public.flashcard_decks SET card_count = card_count + 1 WHERE id = NEW.deck_id;\n  ELSIF TG_OP = 'DELETE' THEN\n    UPDATE public.flashcard_decks SET card_count = card_count - 1 WHERE id = OLD.deck_id;\n  END IF;\n  RETURN NULL;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;\n\nCREATE TRIGGER update_deck_card_count_trigger\nAFTER INSERT OR DELETE ON public.flashcards\nFOR EACH ROW EXECUTE FUNCTION public.update_deck_card_count();\n\n-- Create study_sessions table\nCREATE TABLE public.study_sessions (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  deck_id UUID REFERENCES public.flashcard_decks(id) ON DELETE SET NULL,\n  started_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  ended_at TIMESTAMP WITH TIME ZONE,\n  cards_studied INTEGER DEFAULT 0,\n  correct_count INTEGER DEFAULT 0,\n  total_time_seconds INTEGER DEFAULT 0,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.study_sessions ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Users can view their own sessions\"\nON public.study_sessions FOR SELECT USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can create their own sessions\"\nON public.study_sessions FOR INSERT WITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update their own sessions\"\nON public.study_sessions FOR UPDATE USING (auth.uid() = user_id);\n\n-- Assign default user role on signup\nCREATE OR REPLACE FUNCTION public.assign_default_role()\nRETURNS TRIGGER AS $$\nBEGIN\n  INSERT INTO public.user_roles (user_id, role)\n  VALUES (NEW.id, 'user');\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;\n\nCREATE TRIGGER assign_default_role_trigger\nAFTER INSERT ON auth.users\nFOR EACH ROW EXECUTE FUNCTION public.assign_default_role();" },
  { name: "20251224120345_9bd87ef3-00d3-4871-86c5-c9e62f0a7d36.sql", sql: "-- Create group_members table first (referenced by study_groups RLS)\nCREATE TABLE public.group_members (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  group_id UUID NOT NULL,\n  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  role TEXT DEFAULT 'member' CHECK (role IN ('member', 'admin', 'owner')),\n  joined_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.group_members ENABLE ROW LEVEL SECURITY;\n\n-- Create study_groups table\nCREATE TABLE public.study_groups (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  name TEXT NOT NULL,\n  description TEXT,\n  owner_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  is_private BOOLEAN DEFAULT false,\n  member_count INTEGER DEFAULT 1,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.study_groups ENABLE ROW LEVEL SECURITY;\n\n-- Add FK constraint after both tables exist\nALTER TABLE public.group_members\nADD CONSTRAINT group_members_group_id_fkey\nFOREIGN KEY (group_id) REFERENCES public.study_groups(id) ON DELETE CASCADE;\n\nALTER TABLE public.group_members ADD CONSTRAINT group_members_unique UNIQUE(group_id, user_id);\n\n-- RLS for study_groups\nCREATE POLICY \"Users can view public groups or their groups\"\nON public.study_groups FOR SELECT\nUSING (is_private = false OR owner_id = auth.uid() OR EXISTS (\n  SELECT 1 FROM public.group_members WHERE group_id = id AND user_id = auth.uid()\n));\n\nCREATE POLICY \"Users can create groups\"\nON public.study_groups FOR INSERT WITH CHECK (auth.uid() = owner_id);\n\nCREATE POLICY \"Owners can update their groups\"\nON public.study_groups FOR UPDATE USING (auth.uid() = owner_id);\n\nCREATE POLICY \"Owners can delete their groups\"\nON public.study_groups FOR DELETE USING (auth.uid() = owner_id);\n\n-- RLS for group_members - using security definer function to avoid recursion\nCREATE OR REPLACE FUNCTION public.is_group_member(_group_id UUID, _user_id UUID)\nRETURNS BOOLEAN\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1 FROM public.group_members\n    WHERE group_id = _group_id AND user_id = _user_id\n  )\n$$;\n\nCREATE POLICY \"Users can view members of their groups\"\nON public.group_members FOR SELECT\nUSING (public.is_group_member(group_id, auth.uid()));\n\nCREATE POLICY \"Owners can add members\"\nON public.group_members FOR INSERT\nWITH CHECK (EXISTS (SELECT 1 FROM public.study_groups WHERE id = group_id AND owner_id = auth.uid()) OR user_id = auth.uid());\n\nCREATE POLICY \"Users can leave groups\"\nON public.group_members FOR DELETE\nUSING (user_id = auth.uid());\n\nCREATE TRIGGER update_study_groups_updated_at BEFORE UPDATE ON public.study_groups\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\n-- Auto-add owner as member\nCREATE OR REPLACE FUNCTION public.add_owner_as_group_member()\nRETURNS TRIGGER AS $$\nBEGIN\n  INSERT INTO public.group_members (group_id, user_id, role)\n  VALUES (NEW.id, NEW.owner_id, 'owner');\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;\n\nCREATE TRIGGER add_owner_as_member_trigger\nAFTER INSERT ON public.study_groups\nFOR EACH ROW EXECUTE FUNCTION public.add_owner_as_group_member();\n\n-- Update member count trigger\nCREATE OR REPLACE FUNCTION public.update_group_member_count()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF TG_OP = 'INSERT' THEN\n    UPDATE public.study_groups SET member_count = member_count + 1 WHERE id = NEW.group_id;\n  ELSIF TG_OP = 'DELETE' THEN\n    UPDATE public.study_groups SET member_count = member_count - 1 WHERE id = OLD.group_id;\n  END IF;\n  RETURN NULL;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;\n\nCREATE TRIGGER update_group_member_count_trigger\nAFTER INSERT OR DELETE ON public.group_members\nFOR EACH ROW EXECUTE FUNCTION public.update_group_member_count();\n\n-- Create notifications table\nCREATE TABLE public.notifications (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  type TEXT NOT NULL,\n  title TEXT NOT NULL,\n  message TEXT,\n  read BOOLEAN DEFAULT false,\n  data JSONB,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Users can view their own notifications\"\nON public.notifications FOR SELECT USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update their own notifications\"\nON public.notifications FOR UPDATE USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can delete their own notifications\"\nON public.notifications FOR DELETE USING (auth.uid() = user_id);" },
  { name: "20251225072303_9d6da9b8-f857-423c-9cbb-47a9680127b4.sql", sql: "-- Enable real-time for notifications table\nALTER TABLE public.notifications REPLICA IDENTITY FULL;\n\n-- Add to realtime publication\nALTER PUBLICATION supabase_realtime ADD TABLE public.notifications;" },
  { name: "20251225072449_b8b166df-7971-4e2e-9e3a-1ea55adcd872.sql", sql: "-- Create group messages table for chat\nCREATE TABLE public.group_messages (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  group_id UUID NOT NULL REFERENCES public.study_groups(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL,\n  content TEXT NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- Enable RLS\nALTER TABLE public.group_messages ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies - only group members can see/send messages\nCREATE POLICY \"Group members can view messages\"\nON public.group_messages\nFOR SELECT\nUSING (is_group_member(group_id, auth.uid()));\n\nCREATE POLICY \"Group members can send messages\"\nON public.group_messages\nFOR INSERT\nWITH CHECK (is_group_member(group_id, auth.uid()) AND auth.uid() = user_id);\n\nCREATE POLICY \"Users can delete their own messages\"\nON public.group_messages\nFOR DELETE\nUSING (auth.uid() = user_id);\n\n-- Enable real-time for chat\nALTER TABLE public.group_messages REPLICA IDENTITY FULL;\nALTER PUBLICATION supabase_realtime ADD TABLE public.group_messages;\n\n-- Create shared_notes table for notes shared to groups\nCREATE TABLE public.shared_notes (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  note_id UUID NOT NULL REFERENCES public.notes(id) ON DELETE CASCADE,\n  group_id UUID NOT NULL REFERENCES public.study_groups(id) ON DELETE CASCADE,\n  shared_by UUID NOT NULL,\n  shared_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  UNIQUE(note_id, group_id)\n);\n\n-- Enable RLS\nALTER TABLE public.shared_notes ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies\nCREATE POLICY \"Group members can view shared notes\"\nON public.shared_notes\nFOR SELECT\nUSING (is_group_member(group_id, auth.uid()));\n\nCREATE POLICY \"Note owners can share their notes\"\nON public.shared_notes\nFOR INSERT\nWITH CHECK (\n  is_group_member(group_id, auth.uid()) AND\n  EXISTS (SELECT 1 FROM notes WHERE id = note_id AND user_id = auth.uid())\n);\n\nCREATE POLICY \"Sharers can unshare notes\"\nON public.shared_notes\nFOR DELETE\nUSING (auth.uid() = shared_by);" },
  { name: "20251225075322_5154f3f8-078c-494d-9e36-2f0c3fd22434.sql", sql: "-- Create avatars storage bucket\nINSERT INTO storage.buckets (id, name, public)\nVALUES ('avatars', 'avatars', true)\nON CONFLICT (id) DO NOTHING;\n\n-- Policy: Anyone can view avatars (public bucket)\nCREATE POLICY \"Avatar images are publicly accessible\"\nON storage.objects FOR SELECT\nUSING (bucket_id = 'avatars');\n\n-- Policy: Users can upload their own avatar\nCREATE POLICY \"Users can upload their own avatar\"\nON storage.objects FOR INSERT\nWITH CHECK (\n  bucket_id = 'avatars' \n  AND auth.uid()::text = (storage.foldername(name))[1]\n);\n\n-- Policy: Users can update their own avatar\nCREATE POLICY \"Users can update their own avatar\"\nON storage.objects FOR UPDATE\nUSING (\n  bucket_id = 'avatars' \n  AND auth.uid()::text = (storage.foldername(name))[1]\n);\n\n-- Policy: Users can delete their own avatar\nCREATE POLICY \"Users can delete their own avatar\"\nON storage.objects FOR DELETE\nUSING (\n  bucket_id = 'avatars' \n  AND auth.uid()::text = (storage.foldername(name))[1]\n);" },
  { name: "20251225191157_13305b33-9e79-4680-9524-6fd58fc74705.sql", sql: "-- Create a private bucket for note attachments (PDF/images/etc)\ninsert into storage.buckets (id, name, public)\nvalues ('note-attachments', 'note-attachments', false)\non conflict (id) do nothing;\n\n-- Table to store attachment metadata (NO file blobs)\ncreate table if not exists public.note_attachments (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null,\n  note_id uuid not null references public.notes(id) on delete cascade,\n  bucket_id text not null default 'note-attachments',\n  object_path text not null,\n  file_name text not null,\n  mime_type text null,\n  size_bytes bigint null,\n  created_at timestamptz not null default now()\n);\n\ncreate index if not exists idx_note_attachments_note_id on public.note_attachments(note_id);\ncreate index if not exists idx_note_attachments_user_id on public.note_attachments(user_id);\n\nalter table public.note_attachments enable row level security;\n\n-- RLS: users can only manage their own attachments\ndo $$\nbegin\n  if not exists (\n    select 1 from pg_policies\n    where schemaname='public' and tablename='note_attachments'\n      and policyname='Users can view their own note attachments'\n  ) then\n    create policy \"Users can view their own note attachments\"\n    on public.note_attachments\n    for select\n    using (auth.uid() = user_id);\n  end if;\n\n  if not exists (\n    select 1 from pg_policies\n    where schemaname='public' and tablename='note_attachments'\n      and policyname='Users can add attachments to their own notes'\n  ) then\n    create policy \"Users can add attachments to their own notes\"\n    on public.note_attachments\n    for insert\n    with check (\n      auth.uid() = user_id\n      and exists (\n        select 1 from public.notes n\n        where n.id = note_id and n.user_id = auth.uid()\n      )\n    );\n  end if;\n\n  if not exists (\n    select 1 from pg_policies\n    where schemaname='public' and tablename='note_attachments'\n      and policyname='Users can delete their own note attachments'\n  ) then\n    create policy \"Users can delete their own note attachments\"\n    on public.note_attachments\n    for delete\n    using (auth.uid() = user_id);\n  end if;\nend $$;\n\n-- Storage policies for the note-attachments bucket.\n-- Path convention: {userId}/{noteId}/{filename}\ndo $$\nbegin\n  if not exists (\n    select 1 from pg_policies\n    where schemaname='storage' and tablename='objects'\n      and policyname='Users can view their own note attachment objects'\n  ) then\n    create policy \"Users can view their own note attachment objects\"\n    on storage.objects\n    for select\n    using (\n      bucket_id = 'note-attachments'\n      and auth.uid()::text = (storage.foldername(name))[1]\n    );\n  end if;\n\n  if not exists (\n    select 1 from pg_policies\n    where schemaname='storage' and tablename='objects'\n      and policyname='Users can upload their own note attachment objects'\n  ) then\n    create policy \"Users can upload their own note attachment objects\"\n    on storage.objects\n    for insert\n    with check (\n      bucket_id = 'note-attachments'\n      and auth.uid()::text = (storage.foldername(name))[1]\n    );\n  end if;\n\n  if not exists (\n    select 1 from pg_policies\n    where schemaname='storage' and tablename='objects'\n      and policyname='Users can update their own note attachment objects'\n  ) then\n    create policy \"Users can update their own note attachment objects\"\n    on storage.objects\n    for update\n    using (\n      bucket_id = 'note-attachments'\n      and auth.uid()::text = (storage.foldername(name))[1]\n    )\n    with check (\n      bucket_id = 'note-attachments'\n      and auth.uid()::text = (storage.foldername(name))[1]\n    );\n  end if;\n\n  if not exists (\n    select 1 from pg_policies\n    where schemaname='storage' and tablename='objects'\n      and policyname='Users can delete their own note attachment objects'\n  ) then\n    create policy \"Users can delete their own note attachment objects\"\n    on storage.objects\n    for delete\n    using (\n      bucket_id = 'note-attachments'\n      and auth.uid()::text = (storage.foldername(name))[1]\n    );\n  end if;\nend $$;\n" },
  { name: "20251226124133_ba3ed228-f0c0-4a3c-85cc-dae86c88d2da.sql", sql: "-- Create study_materials table (replaces notes concept for material-first workflow)\nCREATE TABLE public.study_materials (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL,\n  folder_id UUID REFERENCES public.folders(id) ON DELETE SET NULL,\n  title TEXT NOT NULL,\n  file_name TEXT,\n  file_type TEXT, -- pdf, docx, pptx, audio, image\n  file_path TEXT, -- storage path\n  file_size BIGINT,\n  extracted_content TEXT, -- raw extracted text\n  language TEXT DEFAULT 'en',\n  subject TEXT,\n  topic TEXT,\n  processing_status TEXT DEFAULT 'pending', -- pending, processing, completed, failed\n  processing_error TEXT,\n  generate_tutor_notes BOOLEAN DEFAULT true,\n  generate_flashcards BOOLEAN DEFAULT true,\n  generate_questions BOOLEAN DEFAULT true,\n  generate_concept_map BOOLEAN DEFAULT false,\n  created_at TIMESTAMPTZ DEFAULT now(),\n  updated_at TIMESTAMPTZ DEFAULT now()\n);\n\n-- Enable RLS\nALTER TABLE public.study_materials ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for study_materials\nCREATE POLICY \"Users can view their own materials\" ON public.study_materials\n  FOR SELECT USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can create their own materials\" ON public.study_materials\n  FOR INSERT WITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update their own materials\" ON public.study_materials\n  FOR UPDATE USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can delete their own materials\" ON public.study_materials\n  FOR DELETE USING (auth.uid() = user_id);\n\n-- Trigger for updated_at\nCREATE TRIGGER update_study_materials_updated_at\n  BEFORE UPDATE ON public.study_materials\n  FOR EACH ROW\n  EXECUTE FUNCTION public.update_updated_at_column();\n\n-- Create tutor_notes table (AI-generated structured notes)\nCREATE TABLE public.tutor_notes (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  material_id UUID REFERENCES public.study_materials(id) ON DELETE CASCADE NOT NULL,\n  user_id UUID NOT NULL,\n  content JSONB NOT NULL, -- structured: {topics, subtopics, definitions, examples, exam_tips}\n  created_at TIMESTAMPTZ DEFAULT now(),\n  updated_at TIMESTAMPTZ DEFAULT now()\n);\n\nALTER TABLE public.tutor_notes ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Users can view their own tutor notes\" ON public.tutor_notes\n  FOR SELECT USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can create their own tutor notes\" ON public.tutor_notes\n  FOR INSERT WITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update their own tutor notes\" ON public.tutor_notes\n  FOR UPDATE USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can delete their own tutor notes\" ON public.tutor_notes\n  FOR DELETE USING (auth.uid() = user_id);\n\nCREATE TRIGGER update_tutor_notes_updated_at\n  BEFORE UPDATE ON public.tutor_notes\n  FOR EACH ROW\n  EXECUTE FUNCTION public.update_updated_at_column();\n\n-- Create summaries table\nCREATE TABLE public.summaries (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  material_id UUID REFERENCES public.study_materials(id) ON DELETE CASCADE NOT NULL,\n  user_id UUID NOT NULL,\n  summary_type TEXT NOT NULL, -- quick, detailed, bullet_points\n  content TEXT NOT NULL,\n  created_at TIMESTAMPTZ DEFAULT now()\n);\n\nALTER TABLE public.summaries ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Users can view their own summaries\" ON public.summaries\n  FOR SELECT USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can create their own summaries\" ON public.summaries\n  FOR INSERT WITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update their own summaries\" ON public.summaries\n  FOR UPDATE USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can delete their own summaries\" ON public.summaries\n  FOR DELETE USING (auth.uid() = user_id);\n\n-- Create practice_questions table\nCREATE TABLE public.practice_questions (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  material_id UUID REFERENCES public.study_materials(id) ON DELETE CASCADE NOT NULL,\n  user_id UUID NOT NULL,\n  question_type TEXT NOT NULL, -- mcq, short_answer, case_based\n  question TEXT NOT NULL,\n  options JSONB, -- for MCQs: [\"Option A\", \"Option B\", \"Option C\", \"Option D\"]\n  correct_answer TEXT,\n  explanation TEXT,\n  created_at TIMESTAMPTZ DEFAULT now()\n);\n\nALTER TABLE public.practice_questions ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Users can view their own practice questions\" ON public.practice_questions\n  FOR SELECT USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can create their own practice questions\" ON public.practice_questions\n  FOR INSERT WITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update their own practice questions\" ON public.practice_questions\n  FOR UPDATE USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can delete their own practice questions\" ON public.practice_questions\n  FOR DELETE USING (auth.uid() = user_id);\n\n-- Create concept_maps table\nCREATE TABLE public.concept_maps (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  material_id UUID REFERENCES public.study_materials(id) ON DELETE CASCADE NOT NULL,\n  user_id UUID NOT NULL,\n  nodes JSONB NOT NULL, -- [{id, label, x, y, description}]\n  edges JSONB NOT NULL, -- [{source, target, label}]\n  created_at TIMESTAMPTZ DEFAULT now(),\n  updated_at TIMESTAMPTZ DEFAULT now()\n);\n\nALTER TABLE public.concept_maps ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Users can view their own concept maps\" ON public.concept_maps\n  FOR SELECT USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can create their own concept maps\" ON public.concept_maps\n  FOR INSERT WITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update their own concept maps\" ON public.concept_maps\n  FOR UPDATE USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can delete their own concept maps\" ON public.concept_maps\n  FOR DELETE USING (auth.uid() = user_id);\n\nCREATE TRIGGER update_concept_maps_updated_at\n  BEFORE UPDATE ON public.concept_maps\n  FOR EACH ROW\n  EXECUTE FUNCTION public.update_updated_at_column();\n\n-- Create storage bucket for study materials\nINSERT INTO storage.buckets (id, name, public, file_size_limit)\nVALUES ('study-materials', 'study-materials', false, 52428800)\nON CONFLICT (id) DO NOTHING;\n\n-- Storage policies for study-materials bucket\nCREATE POLICY \"Users can view their own study materials files\"\nON storage.objects FOR SELECT\nUSING (bucket_id = 'study-materials' AND auth.uid()::text = (storage.foldername(name))[1]);\n\nCREATE POLICY \"Users can upload their own study materials files\"\nON storage.objects FOR INSERT\nWITH CHECK (bucket_id = 'study-materials' AND auth.uid()::text = (storage.foldername(name))[1]);\n\nCREATE POLICY \"Users can update their own study materials files\"\nON storage.objects FOR UPDATE\nUSING (bucket_id = 'study-materials' AND auth.uid()::text = (storage.foldername(name))[1]);\n\nCREATE POLICY \"Users can delete their own study materials files\"\nON storage.objects FOR DELETE\nUSING (bucket_id = 'study-materials' AND auth.uid()::text = (storage.foldername(name))[1]);" },
  { name: "20251226132801_f0a74756-9359-4b85-90d1-0a0addbc3cc4.sql", sql: "-- Add INSERT policy for notifications table\n-- This allows users/Edge Functions to create notifications for users\nCREATE POLICY \"Users can create their own notifications\"\nON public.notifications FOR INSERT\nWITH CHECK (auth.uid() = user_id);" },
  { name: "20251226153203_c9b866ca-ab31-4bc3-914f-2b07df0271e4.sql", sql: "-- Create a table to store AI-generated flashcards for study materials\nCREATE TABLE public.material_flashcards (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  material_id UUID NOT NULL REFERENCES public.study_materials(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL,\n  front TEXT NOT NULL,\n  back TEXT NOT NULL,\n  hint TEXT,\n  difficulty TEXT DEFAULT 'medium',\n  created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE DEFAULT now()\n);\n\n-- Enable Row Level Security\nALTER TABLE public.material_flashcards ENABLE ROW LEVEL SECURITY;\n\n-- Create policies for user access\nCREATE POLICY \"Users can view their own material flashcards\" \nON public.material_flashcards \nFOR SELECT \nUSING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can create their own material flashcards\" \nON public.material_flashcards \nFOR INSERT \nWITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update their own material flashcards\" \nON public.material_flashcards \nFOR UPDATE \nUSING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can delete their own material flashcards\" \nON public.material_flashcards \nFOR DELETE \nUSING (auth.uid() = user_id);\n\n-- Create index for faster lookups\nCREATE INDEX idx_material_flashcards_material_id ON public.material_flashcards(material_id);\nCREATE INDEX idx_material_flashcards_user_id ON public.material_flashcards(user_id);" },
  { name: "20251228161934_17355fbe-7925-4788-bae0-f8228e00e266.sql", sql: "-- Fix the broken RLS SELECT policy for study_groups\n-- The current policy has a bug: group_members.group_id = group_members.id (should be study_groups.id)\n\nDROP POLICY IF EXISTS \"Users can view public groups or their groups\" ON public.study_groups;\n\nCREATE POLICY \"Users can view public groups or their groups\" \nON public.study_groups \nFOR SELECT \nUSING (\n  (is_private = false) \n  OR (owner_id = auth.uid()) \n  OR (EXISTS (\n    SELECT 1 FROM group_members \n    WHERE group_members.group_id = study_groups.id \n    AND group_members.user_id = auth.uid()\n  ))\n);" },
  { name: "20260105044055_41bd88e8-82d5-45f5-8740-35b0acbb7e23.sql", sql: "-- Add missing RLS policies for production security\n\n-- 1. user_roles table - Prevent unauthorized role modifications\n-- Block all client-side INSERT (only trigger should insert)\nCREATE POLICY \"Block client role inserts\" ON public.user_roles\nFOR INSERT TO authenticated\nWITH CHECK (false);\n\n-- Prevent all updates to roles from client\nCREATE POLICY \"Block client role updates\" ON public.user_roles\nFOR UPDATE TO authenticated\nUSING (false);\n\n-- Prevent all deletes from client\nCREATE POLICY \"Block client role deletes\" ON public.user_roles\nFOR DELETE TO authenticated\nUSING (false);\n\n-- Allow users to read their own roles\nCREATE POLICY \"Users can read own roles\" ON public.user_roles\nFOR SELECT TO authenticated\nUSING (auth.uid() = user_id);\n\n-- 2. group_members table - Only owners can update member roles\nCREATE POLICY \"Owners can update member roles\" ON public.group_members\nFOR UPDATE TO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.study_groups \n    WHERE study_groups.id = group_members.group_id \n    AND study_groups.owner_id = auth.uid()\n  )\n)\nWITH CHECK (\n  EXISTS (\n    SELECT 1 FROM public.study_groups \n    WHERE study_groups.id = group_members.group_id \n    AND study_groups.owner_id = auth.uid()\n  )\n);\n\n-- 3. profiles table - Users can delete their own profile\nCREATE POLICY \"Users can delete own profile\" ON public.profiles\nFOR DELETE TO authenticated\nUSING (auth.uid() = user_id);\n\n-- 4. group_messages table - Users can update their own messages\nCREATE POLICY \"Users can update own messages\" ON public.group_messages\nFOR UPDATE TO authenticated\nUSING (auth.uid() = user_id);\n\n-- 5. shared_notes table - Sharers can update their shared notes\nCREATE POLICY \"Sharers can update shared notes\" ON public.shared_notes\nFOR UPDATE TO authenticated\nUSING (auth.uid() = shared_by);\n\n-- 6. note_attachments table - Users can update their own attachments\nCREATE POLICY \"Users can update own attachments\" ON public.note_attachments\nFOR UPDATE TO authenticated\nUSING (auth.uid() = user_id);" },
  { name: "20260106054136_83e1ede4-c363-4f5e-8e34-cd1c7c15041b.sql", sql: "-- Create subscriptions table to track user subscription status\nCREATE TABLE public.subscriptions (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id UUID NOT NULL,\n  plan TEXT NOT NULL DEFAULT 'free', -- 'free', 'pro', 'team'\n  status TEXT NOT NULL DEFAULT 'active', -- 'active', 'cancelled', 'expired', 'pending'\n  paystack_customer_code TEXT,\n  paystack_subscription_code TEXT,\n  paystack_email_token TEXT,\n  plan_code TEXT, -- Paystack plan code\n  amount INTEGER, -- Amount in cents/kobo\n  currency TEXT DEFAULT 'USD',\n  current_period_start TIMESTAMP WITH TIME ZONE,\n  current_period_end TIMESTAMP WITH TIME ZONE,\n  cancelled_at TIMESTAMP WITH TIME ZONE,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  UNIQUE(user_id)\n);\n\n-- Enable RLS\nALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY;\n\n-- RLS Policies\nCREATE POLICY \"Users can view their own subscription\"\nON public.subscriptions FOR SELECT\nUSING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can insert their own subscription\"\nON public.subscriptions FOR INSERT\nWITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update their own subscription\"\nON public.subscriptions FOR UPDATE\nUSING (auth.uid() = user_id);\n\n-- Create updated_at trigger\nCREATE TRIGGER update_subscriptions_updated_at\nBEFORE UPDATE ON public.subscriptions\nFOR EACH ROW\nEXECUTE FUNCTION public.update_updated_at_column();\n\n-- Create function to get user subscription plan\nCREATE OR REPLACE FUNCTION public.get_user_plan(p_user_id UUID)\nRETURNS TEXT\nLANGUAGE sql\nSTABLE SECURITY DEFINER\nSET search_path = 'public'\nAS $$\n  SELECT COALESCE(\n    (SELECT plan FROM subscriptions WHERE user_id = p_user_id AND status = 'active'),\n    'free'\n  );\n$$;" },
  { name: "20260107175837_151c3baf-18c7-4a1b-8552-2d5a60d91280.sql", sql: "-- Fix INSERT policy to prevent users from creating notifications for other users\nDROP POLICY IF EXISTS \"Users can create their own notifications\" ON public.notifications;\n\nCREATE POLICY \"Users can create their own notifications\" \nON public.notifications \nFOR INSERT \nWITH CHECK (auth.uid() = user_id);" },
  { name: "20260110084139_fc60827b-2e20-469d-a250-9cf43a9dfbc6.sql", sql: "-- Create table for push notification subscriptions\nCREATE TABLE public.push_subscriptions (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id UUID NOT NULL,\n  endpoint TEXT NOT NULL,\n  p256dh_key TEXT NOT NULL,\n  auth_key TEXT NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  UNIQUE(user_id, endpoint)\n);\n\n-- Enable Row Level Security\nALTER TABLE public.push_subscriptions ENABLE ROW LEVEL SECURITY;\n\n-- Create policies for user access\nCREATE POLICY \"Users can view their own push subscriptions\" \nON public.push_subscriptions \nFOR SELECT \nUSING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can create their own push subscriptions\" \nON public.push_subscriptions \nFOR INSERT \nWITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update their own push subscriptions\" \nON public.push_subscriptions \nFOR UPDATE \nUSING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can delete their own push subscriptions\" \nON public.push_subscriptions \nFOR DELETE \nUSING (auth.uid() = user_id);\n\n-- Create trigger for automatic timestamp updates\nCREATE TRIGGER update_push_subscriptions_updated_at\nBEFORE UPDATE ON public.push_subscriptions\nFOR EACH ROW\nEXECUTE FUNCTION public.update_updated_at_column();" },
  { name: "20260117071327_a7aa23dc-9ffa-4a29-aec9-fa875cb5dde8.sql", sql: "-- Create group_invites table for private group invitations\nCREATE TABLE public.group_invites (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  group_id UUID NOT NULL REFERENCES public.study_groups(id) ON DELETE CASCADE,\n  invite_code TEXT NOT NULL UNIQUE,\n  created_by UUID NOT NULL,\n  expires_at TIMESTAMP WITH TIME ZONE NOT NULL,\n  max_uses INTEGER DEFAULT NULL,\n  use_count INTEGER NOT NULL DEFAULT 0,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- Enable RLS\nALTER TABLE public.group_invites ENABLE ROW LEVEL SECURITY;\n\n-- Only group admins/owners can create/view invites\nCREATE POLICY \"Group admins can manage invites\"\nON public.group_invites\nFOR ALL\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.group_members \n    WHERE group_id = group_invites.group_id \n    AND user_id = auth.uid() \n    AND role IN ('owner', 'admin')\n  )\n);\n\n-- Anyone can read invite by code (for joining)\nCREATE POLICY \"Anyone can read invite by code\"\nON public.group_invites\nFOR SELECT\nUSING (true);\n\n-- Create group_message_reads table to track last read message per user per group\nCREATE TABLE public.group_message_reads (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  group_id UUID NOT NULL REFERENCES public.study_groups(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL,\n  last_read_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  UNIQUE(group_id, user_id)\n);\n\n-- Enable RLS\nALTER TABLE public.group_message_reads ENABLE ROW LEVEL SECURITY;\n\n-- Users can manage their own read status\nCREATE POLICY \"Users can manage their own read status\"\nON public.group_message_reads\nFOR ALL\nUSING (auth.uid() = user_id)\nWITH CHECK (auth.uid() = user_id);\n\n-- Function to get unread count for a user in a group\nCREATE OR REPLACE FUNCTION public.get_group_unread_count(p_group_id UUID, p_user_id UUID)\nRETURNS INTEGER AS $$\nDECLARE\n  last_read TIMESTAMP WITH TIME ZONE;\n  unread_count INTEGER;\nBEGIN\n  -- Get last read timestamp\n  SELECT last_read_at INTO last_read\n  FROM public.group_message_reads\n  WHERE group_id = p_group_id AND user_id = p_user_id;\n\n  -- If never read, count all messages\n  IF last_read IS NULL THEN\n    SELECT COUNT(*) INTO unread_count\n    FROM public.group_messages\n    WHERE group_id = p_group_id AND user_id != p_user_id;\n  ELSE\n    SELECT COUNT(*) INTO unread_count\n    FROM public.group_messages\n    WHERE group_id = p_group_id \n      AND user_id != p_user_id \n      AND created_at > last_read;\n  END IF;\n\n  RETURN COALESCE(unread_count, 0);\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;" },
  { name: "20260118045924_dd6ce49f-e62e-4925-8605-90604c720dcf.sql", sql: "-- Create message reactions table\nCREATE TABLE public.message_reactions (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  message_id UUID NOT NULL REFERENCES public.group_messages(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  emoji TEXT NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  UNIQUE(message_id, user_id, emoji)\n);\n\n-- Enable RLS\nALTER TABLE public.message_reactions ENABLE ROW LEVEL SECURITY;\n\n-- Policies for message reactions\nCREATE POLICY \"Users can view reactions in their groups\"\nON public.message_reactions\nFOR SELECT\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.group_messages gm\n    JOIN public.group_members mem ON mem.group_id = gm.group_id\n    WHERE gm.id = message_reactions.message_id\n    AND mem.user_id = auth.uid()\n  )\n);\n\nCREATE POLICY \"Users can add reactions to messages in their groups\"\nON public.message_reactions\nFOR INSERT\nWITH CHECK (\n  auth.uid() = user_id AND\n  EXISTS (\n    SELECT 1 FROM public.group_messages gm\n    JOIN public.group_members mem ON mem.group_id = gm.group_id\n    WHERE gm.id = message_reactions.message_id\n    AND mem.user_id = auth.uid()\n  )\n);\n\nCREATE POLICY \"Users can remove their own reactions\"\nON public.message_reactions\nFOR DELETE\nUSING (auth.uid() = user_id);\n\n-- Create index for faster queries\nCREATE INDEX idx_message_reactions_message_id ON public.message_reactions(message_id);\nCREATE INDEX idx_message_reactions_user_id ON public.message_reactions(user_id);" },
  { name: "20260118050926_127b1af7-20f7-4b39-88ad-1b03cb532ce0.sql", sql: "-- Add reply_to_id column for message threading\nALTER TABLE public.group_messages \nADD COLUMN reply_to_id UUID REFERENCES public.group_messages(id) ON DELETE SET NULL;\n\n-- Create group_message_attachments table for file sharing\nCREATE TABLE public.group_message_attachments (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  message_id UUID NOT NULL REFERENCES public.group_messages(id) ON DELETE CASCADE,\n  file_name TEXT NOT NULL,\n  file_path TEXT NOT NULL,\n  file_size INTEGER,\n  mime_type TEXT,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- Enable RLS on attachments\nALTER TABLE public.group_message_attachments ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for attachments - group members can view/insert\nCREATE POLICY \"Group members can view attachments\"\n  ON public.group_message_attachments\n  FOR SELECT\n  USING (\n    EXISTS (\n      SELECT 1 FROM public.group_messages gm\n      JOIN public.group_members gmbr ON gmbr.group_id = gm.group_id\n      WHERE gm.id = group_message_attachments.message_id\n      AND gmbr.user_id = auth.uid()\n    )\n  );\n\nCREATE POLICY \"Group members can insert attachments\"\n  ON public.group_message_attachments\n  FOR INSERT\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM public.group_messages gm\n      JOIN public.group_members gmbr ON gmbr.group_id = gm.group_id\n      WHERE gm.id = group_message_attachments.message_id\n      AND gmbr.user_id = auth.uid()\n    )\n  );\n\n-- Create index for faster lookups\nCREATE INDEX idx_group_messages_reply_to ON public.group_messages(reply_to_id);\nCREATE INDEX idx_group_message_attachments_message ON public.group_message_attachments(message_id);\n\n-- Create storage bucket for group chat attachments\nINSERT INTO storage.buckets (id, name, public)\nVALUES ('group-attachments', 'group-attachments', true)\nON CONFLICT (id) DO NOTHING;\n\n-- Storage policies for group attachments\nCREATE POLICY \"Anyone can view group attachments\"\n  ON storage.objects FOR SELECT\n  USING (bucket_id = 'group-attachments');\n\nCREATE POLICY \"Authenticated users can upload group attachments\"\n  ON storage.objects FOR INSERT\n  WITH CHECK (bucket_id = 'group-attachments' AND auth.role() = 'authenticated');\n\nCREATE POLICY \"Users can delete their own group attachments\"\n  ON storage.objects FOR DELETE\n  USING (bucket_id = 'group-attachments' AND auth.uid()::text = (storage.foldername(name))[1]);" },
  { name: "20260121012207_eaeedff2-5d08-4df4-8e25-13f3bf72d112.sql", sql: "-- Phase 1: Security Fixes\n\n-- 1.1 Fix group_invites RLS policy - restrict reading to authenticated users\n-- who either own the invite, are group members, or are looking up a specific code\nDROP POLICY IF EXISTS \"Anyone can read invite by code\" ON public.group_invites;\n\nCREATE POLICY \"Authenticated users can read invites by code\"\nON public.group_invites\nFOR SELECT\nUSING (\n  auth.uid() IS NOT NULL\n);\n\n-- 1.2 Add DELETE policies for tables missing them\n\n-- Allow message authors to delete their own attachments\nCREATE POLICY \"Message authors can delete their own attachments\"\nON public.group_message_attachments\nFOR DELETE\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.group_messages gm\n    WHERE gm.id = group_message_attachments.message_id\n    AND gm.user_id = auth.uid()\n  )\n);\n\n-- Allow users to delete their own study sessions\nCREATE POLICY \"Users can delete their own sessions\"\nON public.study_sessions\nFOR DELETE\nUSING (auth.uid() = user_id);\n\n-- 1.3 Create quiz_attempts table for tracking quiz scores\nCREATE TABLE IF NOT EXISTS public.quiz_attempts (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL,\n  material_id UUID NOT NULL REFERENCES public.study_materials(id) ON DELETE CASCADE,\n  score INTEGER NOT NULL,\n  total_questions INTEGER NOT NULL,\n  time_spent_seconds INTEGER,\n  answers JSONB,\n  created_at TIMESTAMPTZ DEFAULT now()\n);\n\n-- Enable RLS on quiz_attempts\nALTER TABLE public.quiz_attempts ENABLE ROW LEVEL SECURITY;\n\n-- Create RLS policies for quiz_attempts\nCREATE POLICY \"Users can view their own quiz attempts\"\nON public.quiz_attempts\nFOR SELECT\nUSING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can create their own quiz attempts\"\nON public.quiz_attempts\nFOR INSERT\nWITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can delete their own quiz attempts\"\nON public.quiz_attempts\nFOR DELETE\nUSING (auth.uid() = user_id);" },
  { name: "20260122044515_836fa2f0-637c-4ef5-9377-8560f88c315a.sql", sql: "-- Create audio_overviews table for storing podcast-style audio content\nCREATE TABLE IF NOT EXISTS public.audio_overviews (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  material_id UUID NOT NULL REFERENCES public.study_materials(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL,\n  style TEXT NOT NULL DEFAULT 'deep_dive',\n  script TEXT,\n  audio_url TEXT,\n  audio_path TEXT,\n  duration_seconds INTEGER,\n  created_at TIMESTAMPTZ DEFAULT now(),\n  updated_at TIMESTAMPTZ DEFAULT now(),\n  UNIQUE(material_id, style)\n);\n\n-- Enable RLS\nALTER TABLE public.audio_overviews ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies\nCREATE POLICY \"Users can view their own audio overviews\"\nON public.audio_overviews FOR SELECT\nUSING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can create their own audio overviews\"\nON public.audio_overviews FOR INSERT\nWITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update their own audio overviews\"\nON public.audio_overviews FOR UPDATE\nUSING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can delete their own audio overviews\"\nON public.audio_overviews FOR DELETE\nUSING (auth.uid() = user_id);\n\n-- Add trigger for updated_at\nCREATE TRIGGER update_audio_overviews_updated_at\nBEFORE UPDATE ON public.audio_overviews\nFOR EACH ROW\nEXECUTE FUNCTION public.update_updated_at_column();\n\n-- Add gamification columns to profiles\nALTER TABLE public.profiles \nADD COLUMN IF NOT EXISTS xp INTEGER DEFAULT 0,\nADD COLUMN IF NOT EXISTS level INTEGER DEFAULT 1,\nADD COLUMN IF NOT EXISTS streak_days INTEGER DEFAULT 0,\nADD COLUMN IF NOT EXISTS last_study_date DATE;\n\n-- Create achievements table\nCREATE TABLE IF NOT EXISTS public.achievements (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  name TEXT NOT NULL,\n  description TEXT NOT NULL,\n  icon TEXT NOT NULL,\n  category TEXT NOT NULL, -- study_time, cards, streaks, mastery\n  tier TEXT NOT NULL DEFAULT 'bronze', -- bronze, silver, gold, platinum\n  requirement_value INTEGER NOT NULL,\n  xp_reward INTEGER NOT NULL DEFAULT 50,\n  created_at TIMESTAMPTZ DEFAULT now()\n);\n\n-- Seed default achievements\nINSERT INTO public.achievements (name, description, icon, category, tier, requirement_value, xp_reward) VALUES\n-- Study Time achievements\n('First Steps', 'Study for 1 hour total', 'clock', 'study_time', 'bronze', 60, 50),\n('Dedicated Learner', 'Study for 10 hours total', 'clock', 'study_time', 'silver', 600, 150),\n('Study Machine', 'Study for 100 hours total', 'clock', 'study_time', 'gold', 6000, 500),\n-- Cards achievements\n('Card Collector', 'Study 100 flashcards', 'layers', 'cards', 'bronze', 100, 50),\n('Card Master', 'Study 1000 flashcards', 'layers', 'cards', 'silver', 1000, 200),\n('Card Legend', 'Study 10000 flashcards', 'layers', 'cards', 'gold', 10000, 1000),\n-- Streak achievements\n('Getting Started', 'Maintain a 3-day streak', 'flame', 'streaks', 'bronze', 3, 30),\n('Week Warrior', 'Maintain a 7-day streak', 'flame', 'streaks', 'bronze', 7, 75),\n('Consistent Learner', 'Maintain a 30-day streak', 'flame', 'streaks', 'silver', 30, 300),\n('Unstoppable', 'Maintain a 100-day streak', 'flame', 'streaks', 'gold', 100, 1000),\n-- Mastery achievements\n('First Mastery', 'Master 10 flashcards', 'award', 'mastery', 'bronze', 10, 50),\n('Knowledge Builder', 'Master 100 flashcards', 'award', 'mastery', 'silver', 100, 250),\n('Expert Level', 'Master 500 flashcards', 'award', 'mastery', 'gold', 500, 750)\nON CONFLICT DO NOTHING;\n\n-- Create user_achievements table\nCREATE TABLE IF NOT EXISTS public.user_achievements (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL,\n  achievement_id UUID NOT NULL REFERENCES public.achievements(id) ON DELETE CASCADE,\n  earned_at TIMESTAMPTZ DEFAULT now(),\n  UNIQUE(user_id, achievement_id)\n);\n\n-- Enable RLS\nALTER TABLE public.user_achievements ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for user_achievements\nCREATE POLICY \"Users can view their own achievements\"\nON public.user_achievements FOR SELECT\nUSING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can earn achievements\"\nON public.user_achievements FOR INSERT\nWITH CHECK (auth.uid() = user_id);\n\n-- Create daily_challenges table\nCREATE TABLE IF NOT EXISTS public.daily_challenges (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL,\n  challenge_type TEXT NOT NULL, -- study_cards, study_time, accuracy\n  target_value INTEGER NOT NULL,\n  current_value INTEGER DEFAULT 0,\n  xp_reward INTEGER NOT NULL DEFAULT 50,\n  challenge_date DATE NOT NULL DEFAULT CURRENT_DATE,\n  completed BOOLEAN DEFAULT false,\n  created_at TIMESTAMPTZ DEFAULT now(),\n  UNIQUE(user_id, challenge_date)\n);\n\n-- Enable RLS\nALTER TABLE public.daily_challenges ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies\nCREATE POLICY \"Users can view their own daily challenges\"\nON public.daily_challenges FOR SELECT\nUSING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update their own daily challenges\"\nON public.daily_challenges FOR UPDATE\nUSING (auth.uid() = user_id);\n\nCREATE POLICY \"System can create daily challenges\"\nON public.daily_challenges FOR INSERT\nWITH CHECK (auth.uid() = user_id);" },
  { name: "20260122044524_9bc792bb-1ecd-44f4-83db-456145a1e240.sql", sql: "-- Enable RLS on achievements table (it was missed)\nALTER TABLE public.achievements ENABLE ROW LEVEL SECURITY;\n\n-- Allow everyone to view achievements (they are public definitions)\nCREATE POLICY \"Everyone can view achievements\"\nON public.achievements FOR SELECT\nUSING (true);" },
  { name: "20260122053504_d45adbc9-e3bd-49ca-b5ab-315825a19b8e.sql", sql: "-- Phase 1: Message Pinning & Editing\nALTER TABLE public.group_messages \n  ADD COLUMN IF NOT EXISTS edited_at TIMESTAMPTZ,\n  ADD COLUMN IF NOT EXISTS is_edited BOOLEAN DEFAULT false,\n  ADD COLUMN IF NOT EXISTS is_pinned BOOLEAN DEFAULT false,\n  ADD COLUMN IF NOT EXISTS pinned_by UUID,\n  ADD COLUMN IF NOT EXISTS pinned_at TIMESTAMPTZ;\n\n-- Full-text search index for messages\nCREATE INDEX IF NOT EXISTS idx_group_messages_content_fts \n  ON public.group_messages USING gin(to_tsvector('english', content));\n\n-- Search function for group messages\nCREATE OR REPLACE FUNCTION public.search_group_messages(\n  p_group_id UUID,\n  p_search_term TEXT,\n  p_limit INTEGER DEFAULT 50\n)\nRETURNS TABLE (\n  id UUID,\n  group_id UUID,\n  user_id UUID,\n  content TEXT,\n  created_at TIMESTAMPTZ,\n  reply_to_id UUID,\n  is_pinned BOOLEAN,\n  rank REAL\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  RETURN QUERY\n  SELECT \n    gm.id,\n    gm.group_id,\n    gm.user_id,\n    gm.content,\n    gm.created_at,\n    gm.reply_to_id,\n    gm.is_pinned,\n    ts_rank(to_tsvector('english', gm.content), plainto_tsquery('english', p_search_term)) as rank\n  FROM public.group_messages gm\n  WHERE gm.group_id = p_group_id\n    AND to_tsvector('english', gm.content) @@ plainto_tsquery('english', p_search_term)\n  ORDER BY rank DESC, gm.created_at DESC\n  LIMIT p_limit;\nEND;\n$$;\n\n-- Phase 3: Scheduled Study Sessions\nCREATE TABLE IF NOT EXISTS public.group_study_sessions (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  group_id UUID NOT NULL REFERENCES public.study_groups(id) ON DELETE CASCADE,\n  title TEXT NOT NULL,\n  description TEXT,\n  scheduled_at TIMESTAMPTZ NOT NULL,\n  duration_minutes INTEGER DEFAULT 60,\n  meeting_link TEXT,\n  created_by UUID NOT NULL,\n  created_at TIMESTAMPTZ DEFAULT now(),\n  updated_at TIMESTAMPTZ DEFAULT now()\n);\n\n-- Enable RLS\nALTER TABLE public.group_study_sessions ENABLE ROW LEVEL SECURITY;\n\n-- RLS Policies for study sessions\nCREATE POLICY \"Group members can view study sessions\"\n  ON public.group_study_sessions\n  FOR SELECT\n  USING (is_group_member(group_id, auth.uid()));\n\nCREATE POLICY \"Group members can create study sessions\"\n  ON public.group_study_sessions\n  FOR INSERT\n  WITH CHECK (is_group_member(group_id, auth.uid()) AND auth.uid() = created_by);\n\nCREATE POLICY \"Session creators can update their sessions\"\n  ON public.group_study_sessions\n  FOR UPDATE\n  USING (auth.uid() = created_by);\n\nCREATE POLICY \"Session creators can delete their sessions\"\n  ON public.group_study_sessions\n  FOR DELETE\n  USING (auth.uid() = created_by);\n\n-- RSVP Table\nCREATE TABLE IF NOT EXISTS public.study_session_rsvps (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  session_id UUID NOT NULL REFERENCES public.group_study_sessions(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL,\n  status TEXT NOT NULL CHECK (status IN ('going', 'maybe', 'not_going')),\n  created_at TIMESTAMPTZ DEFAULT now(),\n  UNIQUE(session_id, user_id)\n);\n\n-- Enable RLS\nALTER TABLE public.study_session_rsvps ENABLE ROW LEVEL SECURITY;\n\n-- RLS Policies for RSVPs\nCREATE POLICY \"Users can view RSVPs for sessions in their groups\"\n  ON public.study_session_rsvps\n  FOR SELECT\n  USING (\n    EXISTS (\n      SELECT 1 FROM public.group_study_sessions gss\n      JOIN public.group_members gm ON gm.group_id = gss.group_id\n      WHERE gss.id = study_session_rsvps.session_id AND gm.user_id = auth.uid()\n    )\n  );\n\nCREATE POLICY \"Users can manage their own RSVPs\"\n  ON public.study_session_rsvps\n  FOR ALL\n  USING (auth.uid() = user_id)\n  WITH CHECK (auth.uid() = user_id);\n\n-- Updated at trigger for study sessions\nCREATE TRIGGER update_group_study_sessions_updated_at\n  BEFORE UPDATE ON public.group_study_sessions\n  FOR EACH ROW\n  EXECUTE FUNCTION public.update_updated_at_column();" },
  { name: "20260122071009_fd1dc439-a67d-48a4-9118-c36689d36d0a.sql", sql: "-- Read receipts table\nCREATE TABLE public.message_read_receipts (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  message_id UUID NOT NULL REFERENCES public.group_messages(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL,\n  read_at TIMESTAMPTZ DEFAULT now(),\n  UNIQUE(message_id, user_id)\n);\n\n-- Enable RLS\nALTER TABLE public.message_read_receipts ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for read receipts\nCREATE POLICY \"Users can view read receipts for messages in their groups\"\nON public.message_read_receipts\nFOR SELECT\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.group_messages gm\n    JOIN public.group_members gmbr ON gm.group_id = gmbr.group_id\n    WHERE gm.id = message_read_receipts.message_id\n    AND gmbr.user_id = auth.uid()\n  )\n);\n\nCREATE POLICY \"Users can create their own read receipts\"\nON public.message_read_receipts\nFOR INSERT\nWITH CHECK (auth.uid() = user_id);\n\n-- Add delivered_at column for delivery tracking\nALTER TABLE public.group_messages ADD COLUMN IF NOT EXISTS delivered_at TIMESTAMPTZ;\n\n-- Add link_preview column for URL previews\nALTER TABLE public.group_messages ADD COLUMN IF NOT EXISTS link_preview JSONB;\n\n-- Add forwarded_from for message forwarding\nALTER TABLE public.group_messages ADD COLUMN IF NOT EXISTS forwarded_from UUID REFERENCES public.group_messages(id);\n\n-- Starred messages table\nCREATE TABLE public.starred_messages (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  message_id UUID NOT NULL REFERENCES public.group_messages(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL,\n  starred_at TIMESTAMPTZ DEFAULT now(),\n  UNIQUE(message_id, user_id)\n);\n\n-- Enable RLS\nALTER TABLE public.starred_messages ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for starred messages\nCREATE POLICY \"Users can view their own starred messages\"\nON public.starred_messages\nFOR SELECT\nUSING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can star messages\"\nON public.starred_messages\nFOR INSERT\nWITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can unstar messages\"\nON public.starred_messages\nFOR DELETE\nUSING (auth.uid() = user_id);\n\n-- Index for faster queries\nCREATE INDEX idx_message_read_receipts_message_id ON public.message_read_receipts(message_id);\nCREATE INDEX idx_starred_messages_user_id ON public.starred_messages(user_id);" },
  { name: "20260122074356_579950fc-f949-4f4f-9713-6dec24aefca3.sql", sql: "-- Create help_categories table\nCREATE TABLE public.help_categories (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  slug TEXT UNIQUE NOT NULL,\n  title TEXT NOT NULL,\n  description TEXT,\n  icon TEXT DEFAULT 'book',\n  display_order INTEGER DEFAULT 0,\n  is_active BOOLEAN DEFAULT true,\n  created_at TIMESTAMPTZ DEFAULT now(),\n  updated_at TIMESTAMPTZ DEFAULT now()\n);\n\n-- Create help_articles table\nCREATE TABLE public.help_articles (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  category_id UUID REFERENCES public.help_categories(id) ON DELETE CASCADE,\n  slug TEXT NOT NULL,\n  title TEXT NOT NULL,\n  content TEXT NOT NULL,\n  summary TEXT,\n  is_faq BOOLEAN DEFAULT false,\n  is_featured BOOLEAN DEFAULT false,\n  display_order INTEGER DEFAULT 0,\n  views INTEGER DEFAULT 0,\n  is_active BOOLEAN DEFAULT true,\n  created_at TIMESTAMPTZ DEFAULT now(),\n  updated_at TIMESTAMPTZ DEFAULT now(),\n  UNIQUE(category_id, slug)\n);\n\n-- Enable RLS\nALTER TABLE public.help_categories ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.help_articles ENABLE ROW LEVEL SECURITY;\n\n-- Public read access for help content (no auth required)\nCREATE POLICY \"Anyone can view active help categories\"\nON public.help_categories\nFOR SELECT\nUSING (is_active = true);\n\nCREATE POLICY \"Anyone can view active help articles\"\nON public.help_articles\nFOR SELECT\nUSING (is_active = true);\n\n-- Create indexes for performance\nCREATE INDEX idx_help_articles_category ON public.help_articles(category_id);\nCREATE INDEX idx_help_articles_slug ON public.help_articles(slug);\nCREATE INDEX idx_help_articles_faq ON public.help_articles(is_faq) WHERE is_faq = true;\nCREATE INDEX idx_help_articles_featured ON public.help_articles(is_featured) WHERE is_featured = true;\n\n-- Seed initial categories\nINSERT INTO public.help_categories (slug, title, description, icon, display_order) VALUES\n  ('getting-started', 'Getting Started', 'Learn the basics of using StudySmart', 'rocket', 1),\n  ('study-materials', 'Study Materials', 'Upload and manage your study content', 'file-text', 2),\n  ('flashcards', 'Flashcards & Quizzes', 'Master content with spaced repetition', 'layers', 3),\n  ('ai-features', 'AI Features', 'Leverage AI for smarter studying', 'sparkles', 4),\n  ('groups', 'Study Groups', 'Collaborate with classmates', 'users', 5),\n  ('account', 'Account & Settings', 'Manage your profile and preferences', 'settings', 6);\n\n-- Seed initial FAQ articles\nINSERT INTO public.help_articles (category_id, slug, title, content, summary, is_faq, display_order) VALUES\n  ((SELECT id FROM public.help_categories WHERE slug = 'getting-started'),\n   'how-to-get-started',\n   'How do I get started with StudySmart?',\n   '## Welcome to StudySmart!\n\nGetting started is easy:\n\n1. **Upload your materials** - Go to the Materials section and upload PDFs, documents, or videos\n2. **Let AI process them** - Our AI will automatically generate summaries, flashcards, and practice questions\n3. **Start studying** - Use the generated content to study smarter, not harder\n\n### Quick Tips\n- Start with one subject to get familiar with the platform\n- Check out the AI-generated flashcards - they''re great for quick reviews\n- Join or create a study group to collaborate with classmates',\n   'Learn how to begin your study journey with StudySmart',\n   true, 1),\n\n  ((SELECT id FROM public.help_categories WHERE slug = 'study-materials'),\n   'supported-file-types',\n   'What file types are supported?',\n   '## Supported File Types\n\nStudySmart supports a variety of file formats:\n\n### Documents\n- **PDF** - Textbooks, lecture notes, research papers\n- **Word Documents** (.docx, .doc)\n- **PowerPoint** (.pptx, .ppt)\n\n### Media\n- **Videos** - YouTube links and uploaded video files\n- **Audio** - Lecture recordings and podcasts\n\n### Size Limits\n- Documents: Up to 50MB per file\n- Videos: Up to 500MB per file\n\n*Pro tip: For best results, ensure your PDFs have selectable text rather than scanned images.*',\n   'Learn about supported document and media formats',\n   true, 2),\n\n  ((SELECT id FROM public.help_categories WHERE slug = 'flashcards'),\n   'spaced-repetition',\n   'What is spaced repetition?',\n   '## Understanding Spaced Repetition\n\nSpaced repetition is a learning technique that optimizes when you review information based on how well you know it.\n\n### How it works\n1. **Rate your recall** - After seeing a flashcard, rate how well you remembered it\n2. **Smart scheduling** - Cards you struggle with appear more frequently\n3. **Long-term retention** - Cards you know well are shown less often\n\n### The Science\nResearch shows spaced repetition can improve retention by up to 200% compared to traditional studying. Our algorithm is based on the proven SM-2 system.\n\n### Tips for Success\n- Study a little bit every day rather than cramming\n- Be honest with your self-ratings\n- Don''t skip the \"hard\" cards - they need the most practice!',\n   'Learn how our smart flashcard system helps you remember better',\n   true, 3),\n\n  ((SELECT id FROM public.help_categories WHERE slug = 'ai-features'),\n   'ai-generated-content',\n   'How does AI generate study content?',\n   '## AI-Powered Study Content\n\nOur AI analyzes your uploaded materials and creates study aids automatically.\n\n### What gets generated\n- **Summaries** - Key points and main concepts\n- **Flashcards** - Question and answer pairs for active recall\n- **Practice Questions** - Multiple choice and short answer questions\n- **Concept Maps** - Visual connections between ideas\n\n### Quality Assurance\n- All content is generated from YOUR materials\n- You can edit or delete any generated content\n- Regenerate content if it doesn''t meet your needs\n\n### Processing Time\n- Small documents: 1-2 minutes\n- Large textbooks: 5-10 minutes\n- Videos: Varies by length',\n   'Understand how AI creates flashcards, summaries, and quizzes',\n   true, 4),\n\n  ((SELECT id FROM public.help_categories WHERE slug = 'groups'),\n   'create-study-group',\n   'How do I create or join a study group?',\n   '## Study Groups\n\nCollaborate with classmates using study groups!\n\n### Creating a Group\n1. Go to the **Groups** section\n2. Click **Create Group**\n3. Add a name and description\n4. Invite members via link or username\n\n### Joining a Group\n- Click an invite link shared by a friend\n- Or search for public groups in your subject area\n\n### Group Features\n- **Shared Notes** - Share study materials with the group\n- **Group Chat** - Discuss topics and ask questions\n- **Study Sessions** - Schedule group study sessions\n- **Voice Notes** - Send audio messages for explanations',\n   'Learn how to collaborate with classmates',\n   true, 5),\n\n  ((SELECT id FROM public.help_categories WHERE slug = 'account'),\n   'subscription-plans',\n   'What are the subscription plans?',\n   '## Subscription Plans\n\n### Free Plan\n- Upload up to 5 materials per month\n- Basic AI summaries and flashcards\n- Join up to 3 study groups\n\n### Pro Plan\n- Unlimited material uploads\n- Advanced AI features (audio overviews, concept maps)\n- Unlimited study groups\n- Priority processing\n- No ads\n\n### How to Upgrade\n1. Go to **Settings** > **Subscription**\n2. Choose your plan\n3. Complete payment via Paystack\n\n*Cancel anytime - no long-term commitment required.*',\n   'Compare free and premium features',\n   true, 6);" },
  { name: "20260122134920_1d2bac25-123f-4c01-84fa-504294917b4a.sql", sql: "-- Add more help articles covering various topics\n\n-- Getting Started Articles\nINSERT INTO help_articles (category_id, slug, title, content, summary, is_faq, is_featured, display_order)\nVALUES \n(\n  (SELECT id FROM help_categories WHERE slug = 'getting-started'),\n  'creating-your-first-note',\n  'Creating Your First Note',\n  '## Creating Notes in Studyly\n\nGetting started with notes is easy! Here''s how to create your first note:\n\n### Step 1: Navigate to Notes\nClick on **Notes** in the sidebar or dashboard to open the notes section.\n\n### Step 2: Create a New Note\nClick the **+ New Note** button in the top right corner.\n\n### Step 3: Add Your Content\n- Give your note a descriptive title\n- Write or paste your study content\n- Use formatting options for headings, lists, and emphasis\n\n### Step 4: Organize with Folders\nCreate folders to keep your notes organized by subject or topic.\n\n### Tips for Effective Notes\n- Use bullet points for key concepts\n- Add images and attachments for visual learning\n- Tag your notes for easy searching later',\n  'Learn how to create and organize your first study note',\n  false,\n  true,\n  2\n),\n(\n  (SELECT id FROM help_categories WHERE slug = 'getting-started'),\n  'navigating-the-dashboard',\n  'Navigating the Dashboard',\n  '## Understanding Your Dashboard\n\nYour dashboard is the central hub for all your study activities.\n\n### Quick Actions\nAt the top, you''ll find quick action buttons to:\n- Create a new note\n- Start a study session\n- Upload study materials\n\n### Recent Activity\nSee your recently accessed notes, flashcard decks, and study materials at a glance.\n\n### Study Progress\nTrack your daily goals, streaks, and XP progress right from the dashboard.\n\n### Notifications\nThe bell icon shows important updates like group messages, session reminders, and achievements.',\n  'Learn your way around the Studyly dashboard',\n  false,\n  false,\n  3\n);\n\n-- Account & Settings Articles\nINSERT INTO help_articles (category_id, slug, title, content, summary, is_faq, is_featured, display_order)\nVALUES \n(\n  (SELECT id FROM help_categories WHERE slug = 'account-settings'),\n  'how-to-delete-account',\n  'How do I delete my account?',\n  '## Deleting Your Account\n\nWe''re sorry to see you go! Here''s how to delete your Studyly account:\n\n### Before You Delete\nPlease note that deleting your account will:\n- Permanently remove all your notes and flashcards\n- Delete your study progress and achievements\n- Remove you from all study groups\n- Cancel any active subscriptions\n\n**This action cannot be undone.**\n\n### Steps to Delete Your Account\n1. Go to **Settings** from the sidebar\n2. Scroll to the **Danger Zone** section\n3. Click **Delete Account**\n4. Confirm by typing \"DELETE\" when prompted\n5. Click the final confirmation button\n\n### Data Export\nWe recommend exporting your data before deleting. See our guide on data export to save your notes and flashcards.\n\n### Need Help?\nIf you''re having issues with the app, please contact us first - we''d love to help resolve any problems before you leave!',\n  'Learn how to permanently delete your Studyly account',\n  true,\n  false,\n  1\n),\n(\n  (SELECT id FROM help_categories WHERE slug = 'account-settings'),\n  'exporting-your-data',\n  'How do I export my data?',\n  '## Exporting Your Data\n\nYou can export your study materials at any time.\n\n### What Can Be Exported\n- **Notes**: Export as Markdown or PDF\n- **Flashcards**: Export as CSV or JSON\n- **Study Materials**: Download original uploaded files\n\n### Exporting Notes\n1. Open the note you want to export\n2. Click the **three-dot menu** (\u22ee)\n3. Select **Export**\n4. Choose your preferred format\n\n### Bulk Export\nTo export all your data:\n1. Go to **Settings**\n2. Find the **Data & Privacy** section\n3. Click **Export All Data**\n4. Wait for the download to be prepared\n5. Download the ZIP file containing all your content\n\n### Export Formats\n- **Markdown (.md)**: Plain text with formatting, great for other note apps\n- **PDF**: Formatted document for printing or sharing\n- **CSV**: Spreadsheet format for flashcards\n- **JSON**: Full data export for backup purposes',\n  'Download and backup your notes, flashcards, and study materials',\n  true,\n  false,\n  2\n),\n(\n  (SELECT id FROM help_categories WHERE slug = 'account-settings'),\n  'changing-password',\n  'How do I change my password?',\n  '## Changing Your Password\n\nKeep your account secure by updating your password regularly.\n\n### Steps to Change Password\n1. Go to **Settings** from the sidebar\n2. Navigate to the **Security** section\n3. Click **Change Password**\n4. Enter your current password\n5. Enter your new password twice\n6. Click **Update Password**\n\n### Password Requirements\nYour new password must:\n- Be at least 8 characters long\n- Include a mix of letters and numbers\n- Not be the same as your current password\n\n### Forgot Your Password?\nIf you can''t remember your current password:\n1. Log out of your account\n2. Click **Forgot Password** on the login page\n3. Enter your email address\n4. Check your email for a reset link\n5. Create a new password',\n  'Update your account password for better security',\n  true,\n  false,\n  3\n),\n(\n  (SELECT id FROM help_categories WHERE slug = 'account-settings'),\n  'managing-notifications',\n  'Managing Notification Settings',\n  '## Notification Preferences\n\nControl how and when Studyly notifies you.\n\n### In-App Notifications\nAccess notification settings in **Settings > Notifications** to toggle:\n- Study reminders\n- Group message alerts\n- Achievement unlocks\n- Session invitations\n\n### Push Notifications\nEnable browser push notifications to receive alerts even when you''re not on the site:\n1. Go to **Settings > Notifications**\n2. Click **Enable Push Notifications**\n3. Allow notifications when your browser prompts\n\n### Email Notifications\nManage email preferences for:\n- Weekly progress summaries\n- Important account updates\n- Group activity digests\n\n### Do Not Disturb\nSet quiet hours to pause all notifications during specific times, perfect for focused study sessions.',\n  'Customize your notification preferences',\n  false,\n  false,\n  4\n);\n\n-- Study Features Articles\nINSERT INTO help_articles (category_id, slug, title, content, summary, is_faq, is_featured, display_order)\nVALUES \n(\n  (SELECT id FROM help_categories WHERE slug = 'study-features'),\n  'keyboard-shortcuts',\n  'Keyboard Shortcuts',\n  '## Keyboard Shortcuts\n\nSpeed up your workflow with these handy shortcuts.\n\n### Global Shortcuts\n| Shortcut | Action |\n|----------|--------|\n| `Ctrl/Cmd + K` | Open global search |\n| `Ctrl/Cmd + N` | Create new note |\n| `Ctrl/Cmd + /` | Open keyboard shortcuts help |\n\n### Note Editor\n| Shortcut | Action |\n|----------|--------|\n| `Ctrl/Cmd + S` | Save note |\n| `Ctrl/Cmd + B` | Bold text |\n| `Ctrl/Cmd + I` | Italic text |\n| `Ctrl/Cmd + Shift + X` | Strikethrough |\n| `Ctrl/Cmd + Shift + H` | Highlight |\n\n### Flashcard Study Mode\n| Shortcut | Action |\n|----------|--------|\n| `Space` | Flip card |\n| `1` | Rate: Again |\n| `2` | Rate: Hard |\n| `3` | Rate: Good |\n| `4` | Rate: Easy |\n| `\u2190` / `\u2192` | Navigate cards |\n| `Esc` | Exit study mode |\n\n### Navigation\n| Shortcut | Action |\n|----------|--------|\n| `G then D` | Go to Dashboard |\n| `G then N` | Go to Notes |\n| `G then F` | Go to Flashcards |\n| `G then M` | Go to Materials |',\n  'Master Studyly with keyboard shortcuts for faster navigation',\n  true,\n  true,\n  1\n),\n(\n  (SELECT id FROM help_categories WHERE slug = 'study-features'),\n  'spaced-repetition-explained',\n  'How Spaced Repetition Works',\n  '## Understanding Spaced Repetition\n\nSpaced repetition is a scientifically-proven learning technique that helps you remember information long-term.\n\n### The Science\nYour brain forgets information over time following a predictable curve. Spaced repetition fights this by reviewing information just before you''re about to forget it.\n\n### How It Works in Studyly\n1. **Study a flashcard** for the first time\n2. **Rate your recall**: Again, Hard, Good, or Easy\n3. The algorithm schedules the next review:\n   - **Again**: See it again in a few minutes\n   - **Hard**: Review tomorrow\n   - **Good**: Review in a few days\n   - **Easy**: Review in a week or more\n\n### Review Intervals\nCards you know well are shown less frequently, while difficult cards appear more often until you master them.\n\n### Best Practices\n- Study daily, even if just for 10 minutes\n- Be honest with your ratings\n- Don''t skip reviews - consistency is key\n- Create clear, focused flashcards',\n  'Learn how our spaced repetition system helps you remember better',\n  true,\n  false,\n  2\n),\n(\n  (SELECT id FROM help_categories WHERE slug = 'study-features'),\n  'ai-study-features',\n  'AI-Powered Study Features',\n  '## AI Features in Studyly\n\nStudyly uses AI to enhance your learning experience.\n\n### AI Flashcard Generation\nUpload study materials and let AI create flashcards for you:\n1. Go to **Study Materials**\n2. Upload a PDF, document, or paste text\n3. Enable **Generate Flashcards** option\n4. Review and edit the generated cards\n\n### AI Summaries\nGet quick summaries of lengthy content:\n- Key points extraction\n- Concept explanations\n- Study-friendly breakdowns\n\n### AI Chat Tutor\nAsk questions about your uploaded materials:\n- Get explanations of complex topics\n- Ask follow-up questions\n- Request examples and analogies\n\n### Concept Maps\nVisualize how ideas connect with auto-generated concept maps from your study materials.\n\n### Practice Questions\nAI generates quiz questions to test your understanding:\n- Multiple choice\n- Short answer\n- True/false',\n  'Discover how AI helps you study smarter',\n  false,\n  true,\n  3\n);\n\n-- Notes & Editor Articles  \nINSERT INTO help_articles (category_id, slug, title, content, summary, is_faq, is_featured, display_order)\nVALUES \n(\n  (SELECT id FROM help_categories WHERE slug = 'notes-editor'),\n  'formatting-notes',\n  'Formatting Your Notes',\n  '## Note Formatting Options\n\nMake your notes more readable and organized with formatting.\n\n### Basic Formatting\n- **Bold**: Select text and click B or use `Ctrl/Cmd + B`\n- *Italic*: Select text and click I or use `Ctrl/Cmd + I`\n- ~~Strikethrough~~: For crossed-out text\n\n### Headings\nUse headings to organize sections:\n- Heading 1 for main topics\n- Heading 2 for subtopics\n- Heading 3 for details\n\n### Lists\n- Bullet lists for unordered items\n- Numbered lists for sequences\n- Checklists for tasks\n\n### Code Blocks\nUse code formatting for:\n- Programming code snippets\n- Formulas\n- Technical notation\n\n### Links and Media\n- Add hyperlinks to reference sources\n- Embed images for visual learning\n- Attach files like PDFs',\n  'Learn all the formatting options available in the note editor',\n  false,\n  false,\n  1\n),\n(\n  (SELECT id FROM help_categories WHERE slug = 'notes-editor'),\n  'importing-documents',\n  'Importing Documents',\n  '## Import Your Existing Notes\n\nBring your study materials from other apps into Studyly.\n\n### Supported Formats\n- **PDF** documents\n- **Word** (.docx) files\n- **Plain text** (.txt) files\n- **Markdown** (.md) files\n\n### How to Import\n1. Open the **Notes** section\n2. Click **Import** button\n3. Select your file or drag and drop\n4. Review the imported content\n5. Make any edits needed\n6. Save your note\n\n### Import Tips\n- Large PDFs may take a moment to process\n- Complex formatting may need adjustment\n- Images in documents will be extracted\n- Consider splitting very long documents\n\n### From Other Note Apps\nTo migrate from apps like Notion, Evernote, or OneNote:\n1. Export your notes as Markdown or PDF\n2. Import the exported files into Studyly',\n  'Import notes from PDFs, Word docs, and other formats',\n  false,\n  false,\n  2\n),\n(\n  (SELECT id FROM help_categories WHERE slug = 'notes-editor'),\n  'organizing-with-folders',\n  'Organizing Notes with Folders',\n  '## Folder Organization\n\nKeep your notes tidy with folders and subfolders.\n\n### Creating Folders\n1. In the Notes section, click **New Folder**\n2. Name your folder (e.g., \"Biology 101\")\n3. Choose a color for easy identification\n\n### Moving Notes to Folders\n- Drag and drop notes into folders\n- Or use the note menu and select **Move to Folder**\n\n### Nested Folders\nCreate subfolders for detailed organization:\n- Main folder: \"Science\"\n  - Subfolder: \"Biology\"\n  - Subfolder: \"Chemistry\"\n\n### Folder Tips\n- Use consistent naming conventions\n- Color-code by subject or priority\n- Don''t nest too deeply (2-3 levels max)\n- Use tags for cross-folder organization',\n  'Create folders to organize your study notes by subject or topic',\n  false,\n  false,\n  3\n);\n\n-- Collaboration Articles\nINSERT INTO help_articles (category_id, slug, title, content, summary, is_faq, is_featured, display_order)\nVALUES \n(\n  (SELECT id FROM help_categories WHERE slug = 'collaboration'),\n  'creating-study-groups',\n  'Creating and Managing Study Groups',\n  '## Study Groups\n\nCollaborate with classmates and study partners in groups.\n\n### Creating a Group\n1. Go to **Groups** in the sidebar\n2. Click **Create Group**\n3. Name your group and add a description\n4. Choose privacy settings (public or private)\n\n### Inviting Members\n- Click **Invite** in your group\n- Share the invite link with friends\n- They can join by clicking the link\n\n### Group Features\n- **Chat**: Real-time messaging with all members\n- **Shared Notes**: Share notes with the group\n- **Study Sessions**: Schedule group study times\n- **Voice Notes**: Send audio messages\n\n### Managing Members\nAs a group owner, you can:\n- Promote members to moderators\n- Remove members if needed\n- Transfer ownership',\n  'Learn how to create groups and study with others',\n  false,\n  false,\n  1\n),\n(\n  (SELECT id FROM help_categories WHERE slug = 'collaboration'),\n  'sharing-notes-groups',\n  'Sharing Notes with Groups',\n  '## Sharing Notes\n\nShare your study notes with group members.\n\n### How to Share\n1. Open the note you want to share\n2. Click the **Share** button\n3. Select the group to share with\n4. Your note will appear in the group''s shared resources\n\n### Shared Note Permissions\n- Group members can view shared notes\n- Only the owner can edit the original\n- Members can copy to their own notes\n\n### Best Practices\n- Share completed, well-organized notes\n- Add context when sharing (what the note covers)\n- Update shared notes to keep them current\n\n### Unsharing Notes\nTo remove a shared note from a group:\n1. Open the note\n2. Click **Share** settings\n3. Remove the group from sharing',\n  'Share your notes with study group members',\n  false,\n  false,\n  2\n);\n\n-- Troubleshooting Articles\nINSERT INTO help_articles (category_id, slug, title, content, summary, is_faq, is_featured, display_order)\nVALUES \n(\n  (SELECT id FROM help_categories WHERE slug = 'troubleshooting'),\n  'app-running-slow',\n  'App Running Slow or Freezing',\n  '## Performance Issues\n\nIf Studyly is running slowly, try these solutions.\n\n### Quick Fixes\n1. **Refresh the page** - Press `Ctrl/Cmd + R`\n2. **Clear browser cache** - Stored data can cause issues\n3. **Close other tabs** - Free up browser memory\n4. **Check your internet** - Slow connection affects performance\n\n### Browser Recommendations\nFor best performance, use:\n- Google Chrome (latest version)\n- Firefox (latest version)\n- Microsoft Edge (latest version)\n\n### Clear Cache Steps\n**Chrome:**\n1. Click the three-dot menu\n2. Go to Settings > Privacy > Clear browsing data\n3. Select \"Cached images and files\"\n4. Click Clear data\n\n### Still Having Issues?\n- Try a different browser\n- Disable browser extensions temporarily\n- Check our status page for outages\n- Contact support with details about the issue',\n  'Fix slow loading and performance problems',\n  true,\n  false,\n  1\n),\n(\n  (SELECT id FROM help_categories WHERE slug = 'troubleshooting'),\n  'content-not-saving',\n  'My Content Isn''t Saving',\n  '## Saving Issues\n\nIf your notes or flashcards aren''t saving, try these solutions.\n\n### Check Your Connection\n- Ensure you have a stable internet connection\n- Look for the sync indicator in the app\n- Try saving again after reconnecting\n\n### Auto-Save\nStudyly auto-saves your work, but you can also:\n- Press `Ctrl/Cmd + S` to force save\n- Look for the \"Saved\" indicator\n\n### Recovery Options\nIf content was lost:\n1. Check your browser''s local storage\n2. Look in the \"Recently Deleted\" section\n3. Contact support - we may be able to recover data\n\n### Preventing Data Loss\n- Wait for the \"Saved\" confirmation\n- Don''t close the tab during uploads\n- Keep a stable internet connection\n- Export important notes as backup',\n  'Troubleshoot content saving and sync issues',\n  true,\n  false,\n  2\n),\n(\n  (SELECT id FROM help_categories WHERE slug = 'troubleshooting'),\n  'login-problems',\n  'Can''t Log In to My Account',\n  '## Login Troubleshooting\n\nHaving trouble accessing your account? Try these solutions.\n\n### Forgot Password\n1. Click **Forgot Password** on the login page\n2. Enter your email address\n3. Check your inbox (and spam folder)\n4. Click the reset link\n5. Create a new password\n\n### Common Issues\n\n**\"Invalid email or password\"**\n- Double-check your email spelling\n- Ensure Caps Lock is off\n- Try resetting your password\n\n**\"Account not found\"**\n- Make sure you''re using the email you signed up with\n- Check if you signed up with Google/social login\n\n**Reset email not arriving**\n- Check your spam/junk folder\n- Wait a few minutes and try again\n- Ensure the email address is correct\n\n### Still Locked Out?\nContact our support team with:\n- The email you used to sign up\n- When you last accessed your account\n- Any error messages you see',\n  'Resolve login and authentication problems',\n  true,\n  false,\n  3\n),\n(\n  (SELECT id FROM help_categories WHERE slug = 'troubleshooting'),\n  'file-upload-errors',\n  'File Upload Not Working',\n  '## Upload Troubleshooting\n\nFix issues with uploading study materials.\n\n### Supported File Types\n- **Documents**: PDF, DOCX, TXT, MD\n- **Images**: PNG, JPG, GIF, WebP\n- **Videos**: MP4, WebM (for video materials)\n\n### File Size Limits\n- Documents: Up to 50MB\n- Images: Up to 10MB\n- Check your subscription for higher limits\n\n### Common Upload Errors\n\n**\"File too large\"**\n- Compress the file or split it\n- Premium users have higher limits\n\n**\"Unsupported format\"**\n- Convert to a supported format\n- PDF works best for documents\n\n**\"Upload failed\"**\n- Check your internet connection\n- Try a smaller file first\n- Clear browser cache and retry\n\n### Tips for Large Files\n- Use PDF for documents (smaller than Word)\n- Compress images before uploading\n- Split very large documents',\n  'Fix file upload errors and learn supported formats',\n  true,\n  false,\n  4\n);\n\n-- Billing & Subscription Articles\nINSERT INTO help_articles (category_id, slug, title, content, summary, is_faq, is_featured, display_order)\nVALUES \n(\n  (SELECT id FROM help_categories WHERE slug = 'billing'),\n  'subscription-plans',\n  'Understanding Subscription Plans',\n  '## Studyly Plans\n\nChoose the plan that fits your study needs.\n\n### Free Plan\nPerfect for getting started:\n- Up to 50 notes\n- 5 flashcard decks\n- Basic AI features\n- Join study groups\n\n### Pro Plan\nFor serious students:\n- Unlimited notes and flashcards\n- Advanced AI features\n- Priority support\n- Audio overviews\n- Concept maps\n\n### Team Plan\nFor study groups and classes:\n- Everything in Pro\n- Group administration\n- Shared workspaces\n- Analytics dashboard\n\n### Comparing Features\n| Feature | Free | Pro | Team |\n|---------|------|-----|------|\n| Notes | 50 | Unlimited | Unlimited |\n| AI Credits | 10/month | 500/month | 2000/month |\n| Support | Community | Priority | Dedicated |',\n  'Compare Free, Pro, and Team subscription options',\n  true,\n  false,\n  1\n),\n(\n  (SELECT id FROM help_categories WHERE slug = 'billing'),\n  'cancel-subscription',\n  'How do I cancel my subscription?',\n  '## Canceling Your Subscription\n\nYou can cancel your subscription at any time.\n\n### Steps to Cancel\n1. Go to **Settings**\n2. Click on **Subscription** or **Billing**\n3. Click **Manage Subscription**\n4. Select **Cancel Subscription**\n5. Confirm your cancellation\n\n### What Happens After Cancellation\n- You keep access until your current period ends\n- Your data remains saved\n- You can resubscribe anytime\n- You''ll move to the Free plan after expiration\n\n### Refunds\n- We offer refunds within 7 days of purchase\n- Contact support for refund requests\n- Partial refunds may be available\n\n### Pausing Instead\nNot ready to cancel? You can pause your subscription:\n1. Go to Subscription settings\n2. Select **Pause Subscription**\n3. Choose pause duration\n4. Your data stays safe until you return',\n  'Cancel or pause your Studyly subscription',\n  true,\n  false,\n  2\n),\n(\n  (SELECT id FROM help_categories WHERE slug = 'billing'),\n  'payment-methods',\n  'Payment Methods and Billing',\n  '## Payment Options\n\nWe accept various payment methods for your convenience.\n\n### Accepted Payment Methods\n- Credit/Debit Cards (Visa, Mastercard)\n- Bank transfers (via Paystack)\n- Mobile money (where available)\n\n### Updating Payment Method\n1. Go to **Settings > Billing**\n2. Click **Update Payment Method**\n3. Enter new payment details\n4. Confirm the change\n\n### Billing Cycle\n- Monthly subscriptions renew on the same date\n- Annual subscriptions save you money\n- You''ll receive email reminders before renewal\n\n### Invoices\n- Access invoices in Settings > Billing\n- Download PDF invoices for records\n- Invoices are emailed after each payment\n\n### Payment Issues\nIf a payment fails:\n- Check your card details\n- Ensure sufficient funds\n- Try a different payment method\n- Contact your bank if issues persist',\n  'Learn about accepted payment methods and billing',\n  false,\n  false,\n  3\n);" },
  { name: "20260122135413_e40d5adb-0c22-411c-bfad-3a9d2e318e87.sql", sql: "-- Create help article feedback table\nCREATE TABLE public.help_article_feedback (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  article_id UUID NOT NULL REFERENCES public.help_articles(id) ON DELETE CASCADE,\n  user_id UUID,  -- Optional: can be null for anonymous feedback\n  is_helpful BOOLEAN NOT NULL,\n  created_at TIMESTAMPTZ DEFAULT now(),\n  -- Prevent duplicate feedback from same user on same article\n  UNIQUE(article_id, user_id)\n);\n\n-- Create index for faster lookups\nCREATE INDEX idx_help_feedback_article ON public.help_article_feedback(article_id);\n\n-- Add helpful/not helpful counts to articles for quick access\nALTER TABLE public.help_articles \nADD COLUMN helpful_count INTEGER DEFAULT 0,\nADD COLUMN not_helpful_count INTEGER DEFAULT 0;\n\n-- Enable RLS\nALTER TABLE public.help_article_feedback ENABLE ROW LEVEL SECURITY;\n\n-- Allow anyone to read feedback counts (via articles table)\n-- Allow authenticated users to submit feedback\nCREATE POLICY \"Anyone can submit feedback\"\nON public.help_article_feedback\nFOR INSERT\nWITH CHECK (true);\n\n-- Users can view their own feedback\nCREATE POLICY \"Users can view own feedback\"\nON public.help_article_feedback\nFOR SELECT\nUSING (auth.uid() = user_id OR user_id IS NULL);\n\n-- Users can update their own feedback\nCREATE POLICY \"Users can update own feedback\"\nON public.help_article_feedback\nFOR UPDATE\nUSING (auth.uid() = user_id);\n\n-- Function to update article feedback counts\nCREATE OR REPLACE FUNCTION public.update_article_feedback_counts()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  IF TG_OP = 'INSERT' THEN\n    IF NEW.is_helpful THEN\n      UPDATE help_articles SET helpful_count = helpful_count + 1 WHERE id = NEW.article_id;\n    ELSE\n      UPDATE help_articles SET not_helpful_count = not_helpful_count + 1 WHERE id = NEW.article_id;\n    END IF;\n  ELSIF TG_OP = 'UPDATE' THEN\n    -- Adjust counts when feedback changes\n    IF OLD.is_helpful AND NOT NEW.is_helpful THEN\n      UPDATE help_articles SET helpful_count = helpful_count - 1, not_helpful_count = not_helpful_count + 1 WHERE id = NEW.article_id;\n    ELSIF NOT OLD.is_helpful AND NEW.is_helpful THEN\n      UPDATE help_articles SET helpful_count = helpful_count + 1, not_helpful_count = not_helpful_count - 1 WHERE id = NEW.article_id;\n    END IF;\n  ELSIF TG_OP = 'DELETE' THEN\n    IF OLD.is_helpful THEN\n      UPDATE help_articles SET helpful_count = helpful_count - 1 WHERE id = OLD.article_id;\n    ELSE\n      UPDATE help_articles SET not_helpful_count = not_helpful_count - 1 WHERE id = OLD.article_id;\n    END IF;\n  END IF;\n  RETURN COALESCE(NEW, OLD);\nEND;\n$$;\n\n-- Trigger to auto-update counts\nCREATE TRIGGER update_feedback_counts\nAFTER INSERT OR UPDATE OR DELETE ON public.help_article_feedback\nFOR EACH ROW\nEXECUTE FUNCTION public.update_article_feedback_counts();" },
  { name: "20260122135422_45f19719-4d09-4508-b0bb-1e06d1df82c8.sql", sql: "-- Drop the overly permissive policy\nDROP POLICY IF EXISTS \"Anyone can submit feedback\" ON public.help_article_feedback;\n\n-- Create a more restrictive policy - only authenticated users can submit feedback\nCREATE POLICY \"Authenticated users can submit feedback\"\nON public.help_article_feedback\nFOR INSERT\nWITH CHECK (auth.uid() IS NOT NULL AND auth.uid() = user_id);" },
  { name: "20260123072718_13e93a57-ea15-4770-96b1-f31e99f0e8db.sql", sql: "-- Email preferences table for granular opt-outs\nCREATE TABLE public.email_preferences (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE,\n  welcome_emails BOOLEAN NOT NULL DEFAULT true,\n  weekly_progress BOOLEAN NOT NULL DEFAULT true,\n  streak_reminders BOOLEAN NOT NULL DEFAULT true,\n  achievement_alerts BOOLEAN NOT NULL DEFAULT true,\n  product_updates BOOLEAN NOT NULL DEFAULT true,\n  unsubscribe_token UUID NOT NULL DEFAULT gen_random_uuid(),\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- Email logs table for analytics\nCREATE TABLE public.email_logs (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL,\n  email_type TEXT NOT NULL,\n  template_name TEXT NOT NULL,\n  subject TEXT NOT NULL,\n  recipient_email TEXT NOT NULL,\n  status TEXT NOT NULL DEFAULT 'sent',\n  resend_id TEXT,\n  metadata JSONB DEFAULT '{}',\n  sent_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- Enable RLS\nALTER TABLE public.email_preferences ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.email_logs ENABLE ROW LEVEL SECURITY;\n\n-- Policies for email_preferences - users can manage their own\nCREATE POLICY \"Users can view their own email preferences\"\n  ON public.email_preferences FOR SELECT\n  USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update their own email preferences\"\n  ON public.email_preferences FOR UPDATE\n  USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can insert their own email preferences\"\n  ON public.email_preferences FOR INSERT\n  WITH CHECK (auth.uid() = user_id);\n\n-- Policies for email_logs - users can view their own logs\nCREATE POLICY \"Users can view their own email logs\"\n  ON public.email_logs FOR SELECT\n  USING (auth.uid() = user_id);\n\n-- Create trigger for updating updated_at\nCREATE TRIGGER update_email_preferences_updated_at\n  BEFORE UPDATE ON public.email_preferences\n  FOR EACH ROW\n  EXECUTE FUNCTION public.update_updated_at_column();\n\n-- Function to auto-create email preferences on user signup\nCREATE OR REPLACE FUNCTION public.handle_new_user_email_preferences()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  INSERT INTO public.email_preferences (user_id)\n  VALUES (NEW.id);\n  RETURN NEW;\nEND;\n$$;\n\n-- Trigger to create email preferences for new users\nCREATE TRIGGER on_auth_user_created_email_preferences\n  AFTER INSERT ON auth.users\n  FOR EACH ROW\n  EXECUTE FUNCTION public.handle_new_user_email_preferences();\n\n-- Create indexes for performance\nCREATE INDEX idx_email_logs_user_id ON public.email_logs(user_id);\nCREATE INDEX idx_email_logs_email_type ON public.email_logs(email_type);\nCREATE INDEX idx_email_logs_sent_at ON public.email_logs(sent_at);\nCREATE INDEX idx_email_preferences_unsubscribe_token ON public.email_preferences(unsubscribe_token);" },
  { name: "20260123075035_01b64234-c1d7-43e2-abdd-d1cc89abc03e.sql", sql: "-- Enable pg_cron extension for scheduling\nCREATE EXTENSION IF NOT EXISTS pg_cron WITH SCHEMA pg_catalog;\n\n-- Enable pg_net extension for HTTP requests\nCREATE EXTENSION IF NOT EXISTS pg_net WITH SCHEMA extensions;\n\n-- Grant usage to postgres role\nGRANT USAGE ON SCHEMA cron TO postgres;\n\n-- Schedule email-onboarding to run daily at 9:00 AM UTC\nSELECT cron.schedule(\n  'email-onboarding-daily',\n  '0 9 * * *',\n  $$\n  SELECT net.http_post(\n    url := 'https://ngcmmvyebvekyutbixee.supabase.co/functions/v1/email-onboarding',\n    headers := jsonb_build_object(\n      'Content-Type', 'application/json',\n      'Authorization', 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im5nY21tdnllYnZla3l1dGJpeGVlIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NjY1NjUwMjUsImV4cCI6MjA4MjE0MTAyNX0.rMePJ1D84TtWk6o1a-e5pIZDV62GW3dkCh337ErpdQE'\n    ),\n    body := jsonb_build_object('time', now())\n  );\n  $$\n);\n\n-- Schedule email-engagement to run daily at 10:00 AM UTC\nSELECT cron.schedule(\n  'email-engagement-daily',\n  '0 10 * * *',\n  $$\n  SELECT net.http_post(\n    url := 'https://ngcmmvyebvekyutbixee.supabase.co/functions/v1/email-engagement',\n    headers := jsonb_build_object(\n      'Content-Type', 'application/json',\n      'Authorization', 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im5nY21tdnllYnZla3l1dGJpeGVlIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NjY1NjUwMjUsImV4cCI6MjA4MjE0MTAyNX0.rMePJ1D84TtWk6o1a-e5pIZDV62GW3dkCh337ErpdQE'\n    ),\n    body := jsonb_build_object('time', now())\n  );\n  $$\n);\n\n-- Schedule check-subscriptions to run daily at 2:00 AM UTC\nSELECT cron.schedule(\n  'check-subscriptions-daily',\n  '0 2 * * *',\n  $$\n  SELECT net.http_post(\n    url := 'https://ngcmmvyebvekyutbixee.supabase.co/functions/v1/check-subscriptions',\n    headers := jsonb_build_object(\n      'Content-Type', 'application/json',\n      'Authorization', 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im5nY21tdnllYnZla3l1dGJpeGVlIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NjY1NjUwMjUsImV4cCI6MjA4MjE0MTAyNX0.rMePJ1D84TtWk6o1a-e5pIZDV62GW3dkCh337ErpdQE'\n    ),\n    body := jsonb_build_object('time', now())\n  );\n  $$\n);" },
  { name: "20260123081059_1ea95d7c-ebd6-4d3a-991f-cbadad8a1090.sql", sql: "-- Create function to send welcome email immediately on user signup\nCREATE OR REPLACE FUNCTION public.send_welcome_email_on_signup()\nRETURNS TRIGGER AS $$\nBEGIN\n  -- Use pg_net to call the send-email edge function\n  -- This sends the welcome email immediately when a new user signs up\n  PERFORM net.http_post(\n    url := 'https://ngcmmvyebvekyutbixee.supabase.co/functions/v1/send-email',\n    headers := jsonb_build_object(\n      'Content-Type', 'application/json',\n      'Authorization', 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im5nY21tdnllYnZla3l1dGJpeGVlIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NjY1NjUwMjUsImV4cCI6MjA4MjE0MTAyNX0.rMePJ1D84TtWk6o1a-e5pIZDV62GW3dkCh337ErpdQE'\n    ),\n    body := jsonb_build_object(\n      'user_id', NEW.user_id,\n      'template', 'welcome'\n    )\n  );\n  \n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;\n\n-- Create trigger to fire after profile is created (which happens on user signup)\nDROP TRIGGER IF EXISTS trigger_send_welcome_email ON public.profiles;\nCREATE TRIGGER trigger_send_welcome_email\n  AFTER INSERT ON public.profiles\n  FOR EACH ROW\n  EXECUTE FUNCTION public.send_welcome_email_on_signup();" },
  { name: "20260123130534_05c50ae5-a74a-48fc-aad2-bbb3df3ccb30.sql", sql: "-- Add policy to allow group members to view each other's basic profile info\n-- This enables proper display of names and avatars in group chats and member lists\nCREATE POLICY \"Group members can view each other's profiles\"\n  ON public.profiles\n  FOR SELECT\n  USING (\n    auth.uid() = user_id \n    OR EXISTS (\n      SELECT 1 FROM group_members gm1\n      JOIN group_members gm2 ON gm1.group_id = gm2.group_id\n      WHERE gm1.user_id = auth.uid()\n      AND gm2.user_id = profiles.user_id\n    )\n  );" },
  { name: "20260124134438_0b0915cd-fbff-4593-a0db-d19f3e60ada2.sql", sql: "-- Group Polls System\nCREATE TABLE public.group_polls (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  group_id UUID NOT NULL REFERENCES public.study_groups(id) ON DELETE CASCADE,\n  question TEXT NOT NULL,\n  created_by UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  ends_at TIMESTAMP WITH TIME ZONE,\n  is_anonymous BOOLEAN NOT NULL DEFAULT false,\n  allow_multiple BOOLEAN NOT NULL DEFAULT false,\n  is_closed BOOLEAN NOT NULL DEFAULT false,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\nCREATE TABLE public.poll_options (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  poll_id UUID NOT NULL REFERENCES public.group_polls(id) ON DELETE CASCADE,\n  option_text TEXT NOT NULL,\n  position INTEGER NOT NULL DEFAULT 0,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\nCREATE TABLE public.poll_votes (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  poll_id UUID NOT NULL REFERENCES public.group_polls(id) ON DELETE CASCADE,\n  option_id UUID NOT NULL REFERENCES public.poll_options(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  UNIQUE (poll_id, option_id, user_id)\n);\n\n-- Add reminder_sent to sessions for tracking\nALTER TABLE public.group_study_sessions \nADD COLUMN IF NOT EXISTS reminder_sent_15min BOOLEAN NOT NULL DEFAULT false,\nADD COLUMN IF NOT EXISTS reminder_sent_1hr BOOLEAN NOT NULL DEFAULT false;\n\n-- Enable RLS\nALTER TABLE public.group_polls ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.poll_options ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.poll_votes ENABLE ROW LEVEL SECURITY;\n\n-- Polls policies (group members can view and create)\nCREATE POLICY \"Group members can view polls\"\nON public.group_polls FOR SELECT\nUSING (public.is_group_member(group_id, auth.uid()));\n\nCREATE POLICY \"Group members can create polls\"\nON public.group_polls FOR INSERT\nWITH CHECK (public.is_group_member(group_id, auth.uid()) AND auth.uid() = created_by);\n\nCREATE POLICY \"Poll creators and admins can update polls\"\nON public.group_polls FOR UPDATE\nUSING (\n  auth.uid() = created_by OR \n  EXISTS (\n    SELECT 1 FROM public.group_members \n    WHERE group_id = group_polls.group_id \n    AND user_id = auth.uid() \n    AND role IN ('owner', 'admin')\n  )\n);\n\nCREATE POLICY \"Poll creators and admins can delete polls\"\nON public.group_polls FOR DELETE\nUSING (\n  auth.uid() = created_by OR \n  EXISTS (\n    SELECT 1 FROM public.group_members \n    WHERE group_id = group_polls.group_id \n    AND user_id = auth.uid() \n    AND role IN ('owner', 'admin')\n  )\n);\n\n-- Poll options policies\nCREATE POLICY \"Group members can view poll options\"\nON public.poll_options FOR SELECT\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.group_polls p\n    WHERE p.id = poll_options.poll_id\n    AND public.is_group_member(p.group_id, auth.uid())\n  )\n);\n\nCREATE POLICY \"Poll creators can insert options\"\nON public.poll_options FOR INSERT\nWITH CHECK (\n  EXISTS (\n    SELECT 1 FROM public.group_polls p\n    WHERE p.id = poll_options.poll_id\n    AND p.created_by = auth.uid()\n  )\n);\n\n-- Poll votes policies\nCREATE POLICY \"Group members can view votes\"\nON public.poll_votes FOR SELECT\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.group_polls p\n    WHERE p.id = poll_votes.poll_id\n    AND public.is_group_member(p.group_id, auth.uid())\n  )\n);\n\nCREATE POLICY \"Group members can vote\"\nON public.poll_votes FOR INSERT\nWITH CHECK (\n  auth.uid() = user_id AND\n  EXISTS (\n    SELECT 1 FROM public.group_polls p\n    WHERE p.id = poll_votes.poll_id\n    AND public.is_group_member(p.group_id, auth.uid())\n    AND (p.is_closed = false)\n    AND (p.ends_at IS NULL OR p.ends_at > now())\n  )\n);\n\nCREATE POLICY \"Users can delete their own votes\"\nON public.poll_votes FOR DELETE\nUSING (auth.uid() = user_id);\n\n-- Indexes for performance\nCREATE INDEX idx_group_polls_group_id ON public.group_polls(group_id);\nCREATE INDEX idx_poll_options_poll_id ON public.poll_options(poll_id);\nCREATE INDEX idx_poll_votes_poll_id ON public.poll_votes(poll_id);\nCREATE INDEX idx_poll_votes_user_id ON public.poll_votes(user_id);" },
  { name: "20260124174017_4c1bf70b-e51d-4219-b84d-aec856254bbe.sql", sql: "-- Security Fix: Strengthen RLS policies for profiles, email_logs, and email_preferences tables\n-- This addresses security findings: profiles_table_public_exposure, email_logs_recipient_exposure, email_preferences_token_exposure\n\n-- 1. Fix profiles table: Add explicit auth check to \"Group members can view each other's profiles\"\nDROP POLICY IF EXISTS \"Group members can view each other's profiles\" ON public.profiles;\n\nCREATE POLICY \"Group members can view each other's profiles\"\nON public.profiles\nFOR SELECT\nUSING (\n  auth.uid() IS NOT NULL AND (\n    auth.uid() = user_id OR\n    EXISTS (\n      SELECT 1 FROM group_members gm1\n      JOIN group_members gm2 ON gm1.group_id = gm2.group_id\n      WHERE gm1.user_id = auth.uid() AND gm2.user_id = profiles.user_id\n    )\n  )\n);\n\n-- 2. Fix email_logs table: Add explicit null check for user_id\nDROP POLICY IF EXISTS \"Users can view their own email logs\" ON public.email_logs;\n\nCREATE POLICY \"Users can view their own email logs\"\nON public.email_logs\nFOR SELECT\nUSING (auth.uid() IS NOT NULL AND user_id IS NOT NULL AND auth.uid() = user_id);\n\n-- 3. Fix email_preferences table: Add explicit auth check for additional safety\nDROP POLICY IF EXISTS \"Users can view their own email preferences\" ON public.email_preferences;\n\nCREATE POLICY \"Users can view their own email preferences\"\nON public.email_preferences\nFOR SELECT\nUSING (auth.uid() IS NOT NULL AND auth.uid() = user_id);\n\n-- Also update the UPDATE policy for consistency\nDROP POLICY IF EXISTS \"Users can update their own email preferences\" ON public.email_preferences;\n\nCREATE POLICY \"Users can update their own email preferences\"\nON public.email_preferences\nFOR UPDATE\nUSING (auth.uid() IS NOT NULL AND auth.uid() = user_id);\n\n-- Also update the INSERT policy for consistency  \nDROP POLICY IF EXISTS \"Users can insert their own email preferences\" ON public.email_preferences;\n\nCREATE POLICY \"Users can insert their own email preferences\"\nON public.email_preferences\nFOR INSERT\nWITH CHECK (auth.uid() IS NOT NULL AND auth.uid() = user_id);" },
  { name: "20260126112542_ff7eba38-cd0b-4333-a782-51fde2d2dd8a.sql", sql: "-- Fix branding in Help Center articles: replace \"Studyly\" with \"Studily\"\nUPDATE help_articles \nSET content = REPLACE(content, 'Studyly', 'Studily'),\n    title = REPLACE(title, 'Studyly', 'Studily'),\n    summary = REPLACE(summary, 'Studyly', 'Studily'),\n    updated_at = now()\nWHERE content LIKE '%Studyly%' \n   OR title LIKE '%Studyly%' \n   OR summary LIKE '%Studyly%';" },
  { name: "20260201152340_8d90f162-9b4b-455a-b8bf-345961e06d00.sql", sql: "-- Help Center Restructure: Clean up and add constraints properly\n\n-- Step 0: Delete duplicate articles keeping only the most recent one\nDELETE FROM help_articles a\nUSING help_articles b\nWHERE a.slug = b.slug\nAND a.id < b.id;\n\n-- Step 1: Add unique constraints using DO blocks\nDO $$ BEGIN\n  ALTER TABLE help_categories ADD CONSTRAINT help_categories_slug_key UNIQUE (slug);\nEXCEPTION WHEN duplicate_table THEN NULL;\nEND $$;\n\nDO $$ BEGIN\n  ALTER TABLE help_articles ADD CONSTRAINT help_articles_slug_key UNIQUE (slug);\nEXCEPTION WHEN duplicate_table THEN NULL;\nEND $$;\n\n-- Step 2: Deactivate ALL existing articles and redundant categories\nUPDATE help_articles SET is_active = false;\nUPDATE help_categories SET is_active = false WHERE slug IN ('study-materials', 'flashcards', 'ai-features', 'account', 'groups');\n\n-- Step 3: Upsert the 6 main categories\nINSERT INTO help_categories (slug, title, description, icon, display_order, is_active) VALUES \n('getting-started', 'Getting Started', 'Learn the basics', 'book', 1, true),\n('notes-editor', 'Notes & Editor', 'Creating and organizing notes', 'help-circle', 2, true),\n('study-features', 'Study Features', 'Flashcards and spaced repetition', 'sparkles', 3, true),\n('collaboration', 'Collaboration', 'Groups and sharing', 'users', 4, true),\n('account-billing', 'Account & Billing', 'Manage your account and payments', 'credit-card', 5, true),\n('troubleshooting', 'Troubleshooting', 'Find solutions to common issues', 'zap', 6, true)\nON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, icon = EXCLUDED.icon, display_order = EXCLUDED.display_order, is_active = true, updated_at = now();\n\n-- Step 4: Delete old articles and insert fresh 24 articles\nDELETE FROM help_articles;\n\n-- Getting Started (5)\nINSERT INTO help_articles (slug, title, summary, content, category_id, display_order, is_active) VALUES\n('create-first-study-set', 'How to create your first study set', 'Learn how to upload materials and create your first AI-powered study set', '# How to Create Your First Study Set\n\nCreating your first study set in Studily is quick and easy.\n\n## Step 1: Navigate to Study Materials\nFrom your dashboard, click on **Study Materials** in the sidebar.\n\n## Step 2: Upload Your Content\nClick **Upload** and select your materials (PDF, Word, text files, or images).\n\n## Step 3: Configure AI Generation\nChoose what to generate: Flashcards, Practice Questions, Summary Notes, or Concept Maps.\n\n## Step 4: Start Studying\nOnce processing is complete, start studying with your personalized materials.\n\n## Related Articles\n- [[quick-start-guide]]\n- [[understanding-dashboard]]', (SELECT id FROM help_categories WHERE slug = 'getting-started'), 1, true),\n\n('quick-start-guide', 'Quick start guide for new users', 'Get up and running with Studily in just 5 minutes', '# Quick Start Guide\n\nWelcome to Studily! Get started in just 5 minutes.\n\n## Step 1: Create Your Account\nSign up with email or Google.\n\n## Step 2: Set Up Your Profile\nAdd your name and study preferences in Settings.\n\n## Step 3: Upload Materials\nGo to Study Materials and upload your first document.\n\n## Step 4: Explore Features\nCheck out Flashcards, Practice Questions, and AI Tutor.\n\n## Related Articles\n- [[create-first-study-set]]\n- [[understanding-dashboard]]', (SELECT id FROM help_categories WHERE slug = 'getting-started'), 2, true),\n\n('understanding-dashboard', 'Understanding your dashboard', 'Navigate your Studily dashboard like a pro', '# Understanding Your Dashboard\n\nYour dashboard is your command center for productive studying.\n\n## Key Features\n- **Study Streak** - Track consecutive study days\n- **XP & Level** - Earn points by studying\n- **Quick Actions** - Fast access to common tasks\n\n## Navigation\nUse the sidebar to access Study Materials, Notes, Flashcards, Groups, and Progress.\n\n## Related Articles\n- [[quick-start-guide]]\n- [[setting-up-profile]]', (SELECT id FROM help_categories WHERE slug = 'getting-started'), 3, true),\n\n('setting-up-profile', 'Setting up your profile', 'Personalize your Studily experience', '# Setting Up Your Profile\n\nPersonalize Studily to match your study style.\n\n## Profile Settings\n1. Go to **Settings** > **Profile**\n2. Add your display name and avatar\n3. Set your study goal and preferences\n\n## Study Preferences\n- Preferred study time (morning/evening)\n- Daily study goal in minutes\n- Notification settings\n\n## Related Articles\n- [[quick-start-guide]]\n- [[changing-password]]', (SELECT id FROM help_categories WHERE slug = 'getting-started'), 4, true),\n\n('importing-existing-materials', 'Importing existing materials', 'Import your existing study materials from other apps', '# Importing Existing Materials\n\nBring your existing study content into Studily.\n\n## Supported Formats\n- PDF, Word (.docx), Text files\n- Images with text (OCR enabled)\n\n## How to Import\n1. Go to Study Materials\n2. Click Upload or drag files\n3. Configure AI options\n4. Click Process\n\n## Related Articles\n- [[create-first-study-set]]\n- [[upload-errors]]', (SELECT id FROM help_categories WHERE slug = 'getting-started'), 5, true),\n\n-- Notes & Editor (4)\n('creating-first-note', 'Creating your first note', 'Learn to create and format notes in Studily', '# Creating Your First Note\n\n## Getting Started\n1. Click **Notes** in the sidebar\n2. Click **+ New Note**\n3. Give your note a title and start writing\n\n## Features\n- Rich text formatting\n- Auto-save\n- AI tools (summarize, generate flashcards)\n\n## Related Articles\n- [[formatting-options]]\n- [[organizing-notes-folders]]', (SELECT id FROM help_categories WHERE slug = 'notes-editor'), 1, true),\n\n('formatting-options', 'Formatting options', 'Format notes for better organization', '# Formatting Options\n\n## Text Styles\n- **Bold** (Ctrl+B), *Italic* (Ctrl+I), Underline (Ctrl+U)\n\n## Structure\n- Headers (H1, H2, H3)\n- Bullet and numbered lists\n- Checklists\n\n## Related Articles\n- [[creating-first-note]]\n- [[adding-images-media]]', (SELECT id FROM help_categories WHERE slug = 'notes-editor'), 2, true),\n\n('organizing-notes-folders', 'Organizing notes in folders', 'Keep your notes organized with folders', '# Organizing Notes in Folders\n\n## Creating Folders\n1. Go to Notes\n2. Click **+ Folder**\n3. Name and color your folder\n\n## Moving Notes\nDrag notes onto folders or use right-click menu.\n\n## Related Articles\n- [[creating-first-note]]', (SELECT id FROM help_categories WHERE slug = 'notes-editor'), 3, true),\n\n('adding-images-media', 'Adding images and media', 'Add images and media to your notes', '# Adding Images and Media\n\n## Adding Images\n- Click the Image icon in toolbar\n- Drag and drop files\n- Paste from clipboard (Ctrl+V)\n\n## Supported Formats\nJPEG, PNG, GIF, WebP (max 5MB)\n\n## Related Articles\n- [[creating-first-note]]\n- [[upload-errors]]', (SELECT id FROM help_categories WHERE slug = 'notes-editor'), 4, true),\n\n-- Study Features (4)\n('using-flashcards-effectively', 'Using flashcards effectively', 'Master the flashcard study mode', '# Using Flashcards Effectively\n\n## Creating Flashcards\n1. Go to Flashcards\n2. Create a deck\n3. Add cards with front/back content\n\n## Study Mode\nRate yourself: Again, Hard, Good, or Easy. The spaced repetition algorithm optimizes your review schedule.\n\n## Related Articles\n- [[spaced-repetition-explained]]\n- [[quiz-mode-guide]]', (SELECT id FROM help_categories WHERE slug = 'study-features'), 1, true),\n\n('spaced-repetition-explained', 'Spaced repetition explained', 'How Studily optimizes your learning with spaced repetition', '# Spaced Repetition Explained\n\n## What Is It?\nA learning technique that shows information at increasing intervals based on your performance.\n\n## How It Works\n- Cards you know appear less frequently\n- Difficult cards appear more often\n- Algorithm adjusts based on your ratings\n\n## Related Articles\n- [[using-flashcards-effectively]]', (SELECT id FROM help_categories WHERE slug = 'study-features'), 2, true),\n\n('ai-tutor-features', 'AI Tutor features', 'Get personalized explanations from the AI tutor', '# AI Tutor Features\n\n## Accessing AI Tutor\n1. Open any Study Material\n2. Click the AI Chat tab\n3. Ask questions about your content\n\n## Capabilities\n- Explain concepts\n- Answer questions\n- Provide examples\n- Simplify complex topics\n\n## Related Articles\n- [[create-first-study-set]]\n- [[quiz-mode-guide]]', (SELECT id FROM help_categories WHERE slug = 'study-features'), 3, true),\n\n('quiz-mode-guide', 'Quiz mode guide', 'Test your knowledge with quiz mode', '# Quiz Mode Guide\n\n## Starting a Quiz\n1. Open a Study Material\n2. Go to Practice Questions tab\n3. Click Start Quiz\n\n## Question Types\nMultiple choice, True/False, Short answer\n\n## Related Articles\n- [[using-flashcards-effectively]]\n- [[ai-tutor-features]]', (SELECT id FROM help_categories WHERE slug = 'study-features'), 4, true),\n\n-- Collaboration (3)\n('sharing-study-sets', 'Sharing study sets', 'Share your study sets with friends and classmates', '# Sharing Study Sets\n\n## Sharing Flashcard Decks\n1. Open a deck\n2. Click Share\n3. Copy and send the link\n\n## Sharing Notes\nMake notes public in Settings or share directly in study groups.\n\n## Related Articles\n- [[creating-study-groups]]', (SELECT id FROM help_categories WHERE slug = 'collaboration'), 1, true),\n\n('creating-study-groups', 'Creating study groups', 'Learn together with study groups', '# Creating Study Groups\n\n## Create a Group\n1. Go to Groups\n2. Click Create Group\n3. Add name, description, privacy settings\n\n## Features\n- Real-time chat\n- Shared notes\n- Study sessions\n- Polls\n\n## Related Articles\n- [[sharing-study-sets]]\n- [[real-time-collaboration]]', (SELECT id FROM help_categories WHERE slug = 'collaboration'), 2, true),\n\n('real-time-collaboration', 'Real-time collaboration', 'Work together on notes in real-time', '# Real-Time Collaboration\n\n## Features\n- Instant messaging\n- Typing indicators\n- Online status\n- Read receipts\n\n## Study Sessions\nSchedule group study sessions with meeting links and RSVP tracking.\n\n## Related Articles\n- [[creating-study-groups]]', (SELECT id FROM help_categories WHERE slug = 'collaboration'), 3, true),\n\n-- Account & Billing (4)\n('changing-password', 'Changing your password', 'Update your account password', '# Changing Your Password\n\n## Steps\n1. Go to Settings > Security\n2. Click Change Password\n3. Enter current and new password\n4. Click Update\n\n## Forgot Password?\nUse the Forgot Password link on the login page.\n\n## Related Articles\n- [[setting-up-profile]]\n- [[contact-support]]', (SELECT id FROM help_categories WHERE slug = 'account-billing'), 1, true),\n\n('managing-subscription', 'Managing subscription', 'Upgrade, downgrade, or cancel your plan', '# Managing Subscription\n\n## View Your Plan\nGo to Settings > Subscription\n\n## Upgrading\nClick Upgrade to Pro and enter payment details.\n\n## Canceling\nClick Cancel Subscription. Access continues until period ends.\n\n## Related Articles\n- [[billing-invoices]]', (SELECT id FROM help_categories WHERE slug = 'account-billing'), 2, true),\n\n('billing-invoices', 'Billing and invoices', 'View and download your invoices', '# Billing and Invoices\n\n## View History\nSettings > Subscription > Billing History\n\n## Download Invoices\nClick the download icon next to any payment.\n\n## Related Articles\n- [[managing-subscription]]', (SELECT id FROM help_categories WHERE slug = 'account-billing'), 3, true),\n\n('deleting-account', 'Deleting your account', 'How to permanently delete your account', '# Deleting Your Account\n\n## Steps\n1. Go to Settings\n2. Scroll to Danger Zone\n3. Click Delete Account\n4. Confirm with password\n\n**Warning:** This permanently removes all your data.\n\n## Related Articles\n- [[contact-support]]', (SELECT id FROM help_categories WHERE slug = 'account-billing'), 4, true),\n\n-- Troubleshooting (4)\n('app-not-loading', 'App not loading', 'Troubleshoot loading issues', '# App Not Loading\n\n## Quick Fixes\n1. Refresh the page (Ctrl+R)\n2. Clear browser cache\n3. Try a different browser\n4. Check internet connection\n\n## Related Articles\n- [[sync-issues]]\n- [[contact-support]]', (SELECT id FROM help_categories WHERE slug = 'troubleshooting'), 1, true),\n\n('sync-issues', 'Sync issues', 'Fix problems with data synchronization', '# Sync Issues\n\n## Troubleshooting\n1. Check internet connection\n2. Refresh the page\n3. Log out and back in\n4. Clear browser cache\n\n## Related Articles\n- [[app-not-loading]]\n- [[contact-support]]', (SELECT id FROM help_categories WHERE slug = 'troubleshooting'), 2, true),\n\n('upload-errors', 'Upload errors', 'Resolve file upload problems', '# Upload Errors\n\n## Common Issues\n- **File Too Large** - Compress or split files\n- **Unsupported Format** - Convert to PDF/JPG/PNG\n- **Upload Failed** - Check connection, retry\n\n## Size Limits\nStudy materials: 25MB, Images: 5MB\n\n## Related Articles\n- [[importing-existing-materials]]\n- [[contact-support]]', (SELECT id FROM help_categories WHERE slug = 'troubleshooting'), 3, true),\n\n('contact-support', 'Contact support', 'Get help from our support team', '# Contact Support\n\n## Email\nsupport@studily.app\n\n## Include\n- Account email\n- Issue description\n- Screenshots if applicable\n\n## Response Times\n- Free: 48 hours\n- Pro: 24 hours\n\n## Related Articles\n- [[app-not-loading]]\n- [[sync-issues]]', (SELECT id FROM help_categories WHERE slug = 'troubleshooting'), 4, true);" },
  { name: "20260204172101_da0acef8-4c87-46e0-83a3-91680737cf84.sql", sql: "-- Add billing_interval column to subscriptions table\nALTER TABLE public.subscriptions \nADD COLUMN IF NOT EXISTS billing_interval TEXT DEFAULT 'monthly';\n\n-- Add comment for documentation\nCOMMENT ON COLUMN public.subscriptions.billing_interval IS 'Billing cycle: monthly or yearly';" },
  { name: "20260205085242_8f515dfd-7c21-4706-8ba0-c4ec29d7a10d.sql", sql: "-- Add trial columns to subscriptions table\nALTER TABLE public.subscriptions \nADD COLUMN IF NOT EXISTS trial_start_date TIMESTAMPTZ,\nADD COLUMN IF NOT EXISTS trial_end_date TIMESTAMPTZ,\nADD COLUMN IF NOT EXISTS trial_used BOOLEAN DEFAULT FALSE;\n\n-- Add comments for documentation\nCOMMENT ON COLUMN public.subscriptions.trial_start_date IS 'Timestamp when free trial started';\nCOMMENT ON COLUMN public.subscriptions.trial_end_date IS 'Timestamp when free trial expires (7 days from start)';\nCOMMENT ON COLUMN public.subscriptions.trial_used IS 'Whether user has already used their free trial';" },
  { name: "20260216183623_44a5fe24-e9e3-4416-ad4f-ee4b6425518e.sql", sql: "\nCREATE TABLE public.payment_attempts (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id uuid NOT NULL,\n  plan text NOT NULL,\n  billing_interval text NOT NULL,\n  paystack_reference text NOT NULL,\n  amount integer,\n  status text NOT NULL DEFAULT 'pending',\n  created_at timestamptz NOT NULL DEFAULT now(),\n  completed_at timestamptz\n);\n\nALTER TABLE public.payment_attempts ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Users can view their own payment attempts\"\n  ON public.payment_attempts FOR SELECT\n  USING (auth.uid() = user_id);\n\nCREATE INDEX idx_payment_attempts_user_id ON public.payment_attempts(user_id);\nCREATE INDEX idx_payment_attempts_status ON public.payment_attempts(status);\nCREATE INDEX idx_payment_attempts_reference ON public.payment_attempts(paystack_reference);\n" },
  { name: "20260216185918_4ecd32f6-e826-495c-9424-7492fa0a6441.sql", sql: "\n-- Automatically start a 7-day free trial when a new user signs up\nCREATE OR REPLACE FUNCTION public.handle_new_user_trial()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $$\nBEGIN\n  INSERT INTO public.subscriptions (user_id, plan, status, trial_start_date, trial_end_date, trial_used)\n  VALUES (\n    NEW.user_id,\n    'pro',\n    'trial',\n    now(),\n    now() + interval '7 days',\n    true\n  );\n  RETURN NEW;\nEND;\n$$;\n\n-- Fire after profile is created (which happens on signup via handle_new_user)\nCREATE TRIGGER on_profile_created_start_trial\nAFTER INSERT ON public.profiles\nFOR EACH ROW\nEXECUTE FUNCTION public.handle_new_user_trial();\n" },
  { name: "20260217155936_53e55340-e352-4ca0-8967-e54e7193e316.sql", sql: "CREATE OR REPLACE FUNCTION public.notify_group_members(\n  p_group_id uuid,\n  p_sender_id uuid,\n  p_type text,\n  p_title text,\n  p_message text,\n  p_data jsonb DEFAULT '{}'::jsonb\n) RETURNS void AS $$\n  INSERT INTO public.notifications (user_id, type, title, message, data)\n  SELECT gm.user_id, p_type, p_title, p_message, p_data\n  FROM public.group_members gm\n  WHERE gm.group_id = p_group_id AND gm.user_id != p_sender_id;\n$$ LANGUAGE sql SECURITY DEFINER SET search_path = 'public';" },
  { name: "20260217161157_cb2a919e-d545-4b09-b686-d5e9988ad0e7.sql", sql: "-- Backfill extracted_content for materials that completed processing but have NULL extracted_content\nUPDATE public.study_materials \nSET extracted_content = 'Title: ' || title || E'\\nSubject: ' || COALESCE(subject, 'General') || E'\\nTopic: ' || COALESCE(topic, title)\nWHERE processing_status = 'completed' AND extracted_content IS NULL;" },
  { name: "20260223150548_2fc624ff-5733-4db1-a749-0ebe3ed8976d.sql", sql: "\n-- Create saved_responses table for pinning AI chat responses\nCREATE TABLE public.saved_responses (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  material_id UUID NOT NULL REFERENCES public.study_materials(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL,\n  content TEXT NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- Enable RLS\nALTER TABLE public.saved_responses ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies\nCREATE POLICY \"Users can view their own saved responses\"\n  ON public.saved_responses FOR SELECT\n  USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can create their own saved responses\"\n  ON public.saved_responses FOR INSERT\n  WITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can delete their own saved responses\"\n  ON public.saved_responses FOR DELETE\n  USING (auth.uid() = user_id);\n\n-- Index for fast lookups\nCREATE INDEX idx_saved_responses_material ON public.saved_responses(material_id, user_id);\n" },
  { name: "20260224113056_eb9554cd-a50e-4f92-aa93-8a1ec02bb904.sql", sql: "UPDATE study_materials \nSET processing_status = 'failed', \n    processing_error = 'Processing timed out. Please retry.',\n    updated_at = now()\nWHERE processing_status = 'processing' \n  AND updated_at < now() - interval '10 minutes';" },
  { name: "20260224130357_60f4c841-29fb-420e-b72b-cde8efa1501d.sql", sql: "\n-- =============================================\n-- NOTEBOOKS: Combined Multi-Material Study\n-- =============================================\n\n-- 1. Create notebooks table\nCREATE TABLE public.notebooks (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id uuid NOT NULL,\n  title text NOT NULL,\n  description text,\n  subject text,\n  topic text,\n  language text NOT NULL DEFAULT 'en',\n  processing_status text DEFAULT 'pending',\n  processing_error text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.notebooks ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Users can view their own notebooks\" ON public.notebooks FOR SELECT USING (auth.uid() = user_id);\nCREATE POLICY \"Users can create their own notebooks\" ON public.notebooks FOR INSERT WITH CHECK (auth.uid() = user_id);\nCREATE POLICY \"Users can update their own notebooks\" ON public.notebooks FOR UPDATE USING (auth.uid() = user_id);\nCREATE POLICY \"Users can delete their own notebooks\" ON public.notebooks FOR DELETE USING (auth.uid() = user_id);\n\nCREATE TRIGGER update_notebooks_updated_at BEFORE UPDATE ON public.notebooks FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\n-- 2. Add notebook_id to study_materials\nALTER TABLE public.study_materials ADD COLUMN notebook_id uuid REFERENCES public.notebooks(id) ON DELETE SET NULL;\nCREATE INDEX idx_study_materials_notebook_id ON public.study_materials(notebook_id);\n\n-- 3. Notebook tutor notes\nCREATE TABLE public.notebook_tutor_notes (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  notebook_id uuid NOT NULL REFERENCES public.notebooks(id) ON DELETE CASCADE,\n  user_id uuid NOT NULL,\n  content jsonb NOT NULL,\n  created_at timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now()\n);\n\nALTER TABLE public.notebook_tutor_notes ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \"Users can view their own notebook tutor notes\" ON public.notebook_tutor_notes FOR SELECT USING (auth.uid() = user_id);\nCREATE POLICY \"Users can create their own notebook tutor notes\" ON public.notebook_tutor_notes FOR INSERT WITH CHECK (auth.uid() = user_id);\nCREATE POLICY \"Users can update their own notebook tutor notes\" ON public.notebook_tutor_notes FOR UPDATE USING (auth.uid() = user_id);\nCREATE POLICY \"Users can delete their own notebook tutor notes\" ON public.notebook_tutor_notes FOR DELETE USING (auth.uid() = user_id);\n\n-- 4. Notebook summaries\nCREATE TABLE public.notebook_summaries (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  notebook_id uuid NOT NULL REFERENCES public.notebooks(id) ON DELETE CASCADE,\n  user_id uuid NOT NULL,\n  summary_type text NOT NULL,\n  content text NOT NULL,\n  created_at timestamptz DEFAULT now()\n);\n\nALTER TABLE public.notebook_summaries ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \"Users can view their own notebook summaries\" ON public.notebook_summaries FOR SELECT USING (auth.uid() = user_id);\nCREATE POLICY \"Users can create their own notebook summaries\" ON public.notebook_summaries FOR INSERT WITH CHECK (auth.uid() = user_id);\nCREATE POLICY \"Users can update their own notebook summaries\" ON public.notebook_summaries FOR UPDATE USING (auth.uid() = user_id);\nCREATE POLICY \"Users can delete their own notebook summaries\" ON public.notebook_summaries FOR DELETE USING (auth.uid() = user_id);\n\n-- 5. Notebook flashcards\nCREATE TABLE public.notebook_flashcards (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  notebook_id uuid NOT NULL REFERENCES public.notebooks(id) ON DELETE CASCADE,\n  user_id uuid NOT NULL,\n  front text NOT NULL,\n  back text NOT NULL,\n  hint text,\n  difficulty text DEFAULT 'medium',\n  created_at timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now()\n);\n\nALTER TABLE public.notebook_flashcards ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \"Users can view their own notebook flashcards\" ON public.notebook_flashcards FOR SELECT USING (auth.uid() = user_id);\nCREATE POLICY \"Users can create their own notebook flashcards\" ON public.notebook_flashcards FOR INSERT WITH CHECK (auth.uid() = user_id);\nCREATE POLICY \"Users can update their own notebook flashcards\" ON public.notebook_flashcards FOR UPDATE USING (auth.uid() = user_id);\nCREATE POLICY \"Users can delete their own notebook flashcards\" ON public.notebook_flashcards FOR DELETE USING (auth.uid() = user_id);\n\n-- 6. Notebook practice questions\nCREATE TABLE public.notebook_practice_questions (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  notebook_id uuid NOT NULL REFERENCES public.notebooks(id) ON DELETE CASCADE,\n  user_id uuid NOT NULL,\n  question_type text NOT NULL,\n  question text NOT NULL,\n  options jsonb,\n  correct_answer text,\n  explanation text,\n  created_at timestamptz DEFAULT now()\n);\n\nALTER TABLE public.notebook_practice_questions ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \"Users can view their own notebook practice questions\" ON public.notebook_practice_questions FOR SELECT USING (auth.uid() = user_id);\nCREATE POLICY \"Users can create their own notebook practice questions\" ON public.notebook_practice_questions FOR INSERT WITH CHECK (auth.uid() = user_id);\nCREATE POLICY \"Users can update their own notebook practice questions\" ON public.notebook_practice_questions FOR UPDATE USING (auth.uid() = user_id);\nCREATE POLICY \"Users can delete their own notebook practice questions\" ON public.notebook_practice_questions FOR DELETE USING (auth.uid() = user_id);\n\n-- 7. Notebook concept maps\nCREATE TABLE public.notebook_concept_maps (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  notebook_id uuid NOT NULL REFERENCES public.notebooks(id) ON DELETE CASCADE,\n  user_id uuid NOT NULL,\n  nodes jsonb NOT NULL,\n  edges jsonb NOT NULL,\n  created_at timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now()\n);\n\nALTER TABLE public.notebook_concept_maps ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \"Users can view their own notebook concept maps\" ON public.notebook_concept_maps FOR SELECT USING (auth.uid() = user_id);\nCREATE POLICY \"Users can create their own notebook concept maps\" ON public.notebook_concept_maps FOR INSERT WITH CHECK (auth.uid() = user_id);\nCREATE POLICY \"Users can update their own notebook concept maps\" ON public.notebook_concept_maps FOR UPDATE USING (auth.uid() = user_id);\nCREATE POLICY \"Users can delete their own notebook concept maps\" ON public.notebook_concept_maps FOR DELETE USING (auth.uid() = user_id);\n" },
  { name: "20260401060308_22f7b248-1568-4631-ad45-5d599510448b.sql", sql: "\nCREATE OR REPLACE FUNCTION public.handle_new_user_trial()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nBEGIN\n  INSERT INTO public.subscriptions (user_id, plan, status, trial_start_date, trial_end_date, trial_used)\n  VALUES (\n    NEW.user_id,\n    'pro',\n    'trial',\n    now(),\n    now() + interval '3 days',\n    true\n  );\n  RETURN NEW;\nEND;\n$function$;\n" },
  { name: "20260401061329_1d2839c6-c697-41d0-b122-224567a8f2bf.sql", sql: "\n-- 1. Fix subscription privilege escalation: Remove user INSERT and UPDATE policies\n-- Subscriptions should only be managed by the trigger (trial) and edge functions (payments)\nDROP POLICY IF EXISTS \"Users can insert their own subscription\" ON public.subscriptions;\nDROP POLICY IF EXISTS \"Users can update their own subscription\" ON public.subscriptions;\n\n-- 2. Fix group-attachments public bucket: Make it private\nUPDATE storage.buckets SET public = false WHERE id = 'group-attachments';\n\n-- Fix storage SELECT policy: require group membership instead of open access\nDROP POLICY IF EXISTS \"Anyone can view group attachments\" ON storage.objects;\n\nCREATE POLICY \"Group members can view group attachments\"\nON storage.objects\nFOR SELECT\nUSING (\n  bucket_id = 'group-attachments'\n  AND auth.uid() IS NOT NULL\n  AND EXISTS (\n    SELECT 1\n    FROM public.group_message_attachments gma\n    JOIN public.group_messages gm ON gm.id = gma.message_id\n    JOIN public.group_members gmb ON gmb.group_id = gm.group_id\n    WHERE gma.file_path = name\n    AND gmb.user_id = auth.uid()\n  )\n);\n\n-- 3. Fix group invites: Replace overly permissive policy with authenticated-only\nDROP POLICY IF EXISTS \"Anyone can read invite by code\" ON public.group_invites;\n\n-- The existing \"Authenticated users can read invites by code\" policy already handles this,\n-- but let's verify it exists and covers the join flow\n-- (from the scan results, this policy already exists with auth.uid() IS NOT NULL check)\n" },
  { name: "20260401061831_b03bcd8f-70fa-4522-b7db-52b69c9505a0.sql", sql: "\n-- Drop the overly permissive SELECT policy\nDROP POLICY IF EXISTS \"Authenticated users can read invites by code\" ON public.group_invites;\n\n-- Create a secure RPC for validating and joining via invite code\nCREATE OR REPLACE FUNCTION public.validate_and_join_invite(p_invite_code TEXT)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_invite RECORD;\n  v_user_id uuid;\n  v_existing RECORD;\n  v_result jsonb;\nBEGIN\n  v_user_id := auth.uid();\n  IF v_user_id IS NULL THEN\n    RETURN jsonb_build_object('error', 'Not authenticated');\n  END IF;\n\n  -- Find the invite\n  SELECT * INTO v_invite\n  FROM group_invites\n  WHERE invite_code = p_invite_code\n    AND expires_at > now();\n\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object('error', 'Invalid or expired invite code');\n  END IF;\n\n  -- Check max uses\n  IF v_invite.max_uses IS NOT NULL AND v_invite.use_count >= v_invite.max_uses THEN\n    RETURN jsonb_build_object('error', 'This invite has reached its maximum uses');\n  END IF;\n\n  -- Check if already a member\n  SELECT id INTO v_existing\n  FROM group_members\n  WHERE group_id = v_invite.group_id AND user_id = v_user_id;\n\n  IF FOUND THEN\n    RETURN jsonb_build_object('error', 'You are already a member of this group');\n  END IF;\n\n  -- Join the group\n  INSERT INTO group_members (group_id, user_id, role)\n  VALUES (v_invite.group_id, v_user_id, 'member');\n\n  -- Increment use count\n  UPDATE group_invites SET use_count = use_count + 1 WHERE id = v_invite.id;\n\n  RETURN jsonb_build_object('success', true, 'group_id', v_invite.group_id);\nEND;\n$$;\n" },
  { name: "20260403103408_9c8adbe8-e5b3-4c21-b1f2-25524ce71198.sql", sql: "\n-- Check if user_achievements table exists and has permissive INSERT policy\nDO $$\nBEGIN\n  -- Drop overly permissive INSERT policy on user_achievements if it exists\n  IF EXISTS (\n    SELECT 1 FROM pg_policies \n    WHERE tablename = 'user_achievements' \n    AND cmd = 'INSERT'\n    AND qual IS NULL\n    AND with_check::text LIKE '%auth.uid()%'\n  ) THEN\n    DROP POLICY IF EXISTS \"Users can earn achievements\" ON public.user_achievements;\n  END IF;\nEND $$;\n\n-- Ensure email_logs has no INSERT policy for authenticated users (writes are service-role only)\n-- The table already blocks INSERT per the schema review, so this is a safety net\nDO $$\nBEGIN\n  -- Drop any INSERT policies that might exist\n  IF EXISTS (\n    SELECT 1 FROM pg_policies WHERE tablename = 'email_logs' AND cmd = 'INSERT'\n  ) THEN\n    EXECUTE (\n      SELECT string_agg('DROP POLICY IF EXISTS ' || quote_ident(policyname) || ' ON public.email_logs;', ' ')\n      FROM pg_policies WHERE tablename = 'email_logs' AND cmd = 'INSERT'\n    );\n  END IF;\nEND $$;\n\n-- Ensure email_logs has no DELETE policy for authenticated users\nDO $$\nBEGIN\n  IF EXISTS (\n    SELECT 1 FROM pg_policies WHERE tablename = 'email_logs' AND cmd = 'DELETE'\n  ) THEN\n    EXECUTE (\n      SELECT string_agg('DROP POLICY IF EXISTS ' || quote_ident(policyname) || ' ON public.email_logs;', ' ')\n      FROM pg_policies WHERE tablename = 'email_logs' AND cmd = 'DELETE'\n    );\n  END IF;\nEND $$;\n\n-- Ensure email_logs has no UPDATE policy for authenticated users\nDO $$\nBEGIN\n  IF EXISTS (\n    SELECT 1 FROM pg_policies WHERE tablename = 'email_logs' AND cmd = 'UPDATE'\n  ) THEN\n    EXECUTE (\n      SELECT string_agg('DROP POLICY IF EXISTS ' || quote_ident(policyname) || ' ON public.email_logs;', ' ')\n      FROM pg_policies WHERE tablename = 'email_logs' AND cmd = 'UPDATE'\n    );\n  END IF;\nEND $$;\n" },
  { name: "20260403103824_b033c4c1-6a82-4028-a3f8-b55acae3e1d4.sql", sql: "\n-- Recreate the welcome email trigger function to use service role key\nCREATE OR REPLACE FUNCTION public.send_welcome_email_on_signup()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $function$\nDECLARE\n  service_key text;\nBEGIN\n  -- Read the service role key from Supabase's built-in GUC\n  service_key := coalesce(\n    current_setting('supabase.service_role_key', true),\n    current_setting('app.settings.service_role_key', true)\n  );\n\n  PERFORM net.http_post(\n    url := 'https://ngcmmvyebvekyutbixee.supabase.co/functions/v1/send-email',\n    headers := jsonb_build_object(\n      'Content-Type', 'application/json',\n      'Authorization', 'Bearer ' || service_key\n    ),\n    body := jsonb_build_object(\n      'user_id', NEW.user_id,\n      'template', 'welcome'\n    )\n  );\n  \n  RETURN NEW;\nEND;\n$function$;\n" },
  { name: "20260404091740_33a50db5-7f3b-4c30-9904-ce343602c094.sql", sql: "ALTER TABLE public.flashcard_decks ADD COLUMN source_material_id uuid REFERENCES public.study_materials(id) ON DELETE SET NULL;" },
  { name: "20260416185958_f6aed131-16b8-4fd2-8ab3-305479d264be.sql", sql: "-- Enable required extensions\nCREATE EXTENSION IF NOT EXISTS pg_cron;\nCREATE EXTENSION IF NOT EXISTS pg_net;\n\n-- Remove existing schedule if present (idempotent)\nDO $$\nBEGIN\n  PERFORM cron.unschedule('reconcile-payments-every-10min');\nEXCEPTION WHEN OTHERS THEN NULL;\nEND $$;\n\n-- Schedule reconciliation to run every 10 minutes\nSELECT cron.schedule(\n  'reconcile-payments-every-10min',\n  '*/10 * * * *',\n  $$\n  SELECT net.http_post(\n    url := 'https://ngcmmvyebvekyutbixee.supabase.co/functions/v1/reconcile-payments',\n    headers := jsonb_build_object(\n      'Content-Type', 'application/json',\n      'Authorization', 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im5nY21tdnllYnZla3l1dGJpeGVlIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NjY1NjUwMjUsImV4cCI6MjA4MjE0MTAyNX0.rMePJ1D84TtWk6o1a-e5pIZDV62GW3dkCh337ErpdQE'\n    ),\n    body := jsonb_build_object('triggered_at', now())\n  );\n  $$\n);\n\n-- One-off immediate run to recover any currently stuck payments\nSELECT net.http_post(\n  url := 'https://ngcmmvyebvekyutbixee.supabase.co/functions/v1/reconcile-payments',\n  headers := jsonb_build_object(\n    'Content-Type', 'application/json',\n    'Authorization', 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im5nY21tdnllYnZla3l1dGJpeGVlIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NjY1NjUwMjUsImV4cCI6MjA4MjE0MTAyNX0.rMePJ1D84TtWk6o1a-e5pIZDV62GW3dkCh337ErpdQE'\n  ),\n  body := jsonb_build_object('triggered_at', now(), 'source', 'migration_oneoff')\n);" },
  { name: "20260531071355_16dea435-fd54-4273-b983-fb0da7fe82ab.sql", sql: "CREATE OR REPLACE FUNCTION public.get_group_unread_counts(p_group_ids uuid[])\nRETURNS TABLE(group_id uuid, count bigint)\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_user uuid := auth.uid();\nBEGIN\n  IF v_user IS NULL THEN\n    RETURN;\n  END IF;\n\n  RETURN QUERY\n  SELECT g.id AS group_id,\n         COUNT(gm.id) FILTER (\n           WHERE gm.user_id <> v_user\n             AND (r.last_read_at IS NULL OR gm.created_at > r.last_read_at)\n         ) AS count\n  FROM unnest(p_group_ids) AS g(id)\n  LEFT JOIN public.group_message_reads r\n    ON r.group_id = g.id AND r.user_id = v_user\n  LEFT JOIN public.group_messages gm\n    ON gm.group_id = g.id\n  GROUP BY g.id;\nEND;\n$$;\n\nGRANT EXECUTE ON FUNCTION public.get_group_unread_counts(uuid[]) TO authenticated;" },
  { name: "20260531185222_25ad0292-05c1-4b44-a9a8-8f1d7a024ef2.sql", sql: "\n-- 1. Tighten group-attachments INSERT to verify group membership via path\nDROP POLICY IF EXISTS \"Authenticated users can upload group attachments\" ON storage.objects;\nCREATE POLICY \"Group members can upload group attachments\"\nON storage.objects FOR INSERT TO authenticated\nWITH CHECK (\n  bucket_id = 'group-attachments'\n  AND (auth.uid())::text = (storage.foldername(name))[1]\n);\n\n-- 2. Restrict client writes on email_logs (service-role only)\nREVOKE INSERT, UPDATE, DELETE ON public.email_logs FROM anon, authenticated;\nCREATE POLICY \"No client writes on email_logs\"\nON public.email_logs AS RESTRICTIVE FOR ALL TO anon, authenticated\nUSING (false) WITH CHECK (false);\n\n-- 3. Restrict client writes on payment_attempts (service-role only)\nREVOKE INSERT, UPDATE, DELETE ON public.payment_attempts FROM anon, authenticated;\nCREATE POLICY \"No client writes on payment_attempts\"\nON public.payment_attempts AS RESTRICTIVE FOR ALL TO anon, authenticated\nUSING (true) WITH CHECK (false);\n\n-- 4. Restrict client writes on user_achievements (service-role only)\nREVOKE INSERT, UPDATE, DELETE ON public.user_achievements FROM anon, authenticated;\nCREATE POLICY \"No client writes on user_achievements\"\nON public.user_achievements AS RESTRICTIVE FOR ALL TO anon, authenticated\nUSING (true) WITH CHECK (false);\n\n-- 5. Lock down SECURITY DEFINER function EXECUTE to authenticated only (revoke from anon/public)\nREVOKE EXECUTE ON FUNCTION public.get_group_unread_count(uuid, uuid) FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.get_group_unread_counts(uuid[]) FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.get_user_plan(uuid) FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.has_role(uuid, app_role) FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.is_group_member(uuid, uuid) FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.notify_group_members(uuid, uuid, text, text, text, jsonb) FROM PUBLIC, anon, authenticated;\nREVOKE EXECUTE ON FUNCTION public.search_group_messages(uuid, text, integer) FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.validate_and_join_invite(text) FROM PUBLIC, anon;\n\n-- 6. Realtime channel authorization \u2014 restrict subscriptions to owners / group members\nALTER TABLE IF EXISTS realtime.messages ENABLE ROW LEVEL SECURITY;\n\nDROP POLICY IF EXISTS \"Authenticated can read own notification channel\" ON realtime.messages;\nCREATE POLICY \"Authenticated can read own notification channel\"\nON realtime.messages FOR SELECT TO authenticated\nUSING (\n  realtime.topic() = 'notifications-realtime'\n  OR realtime.topic() = 'notifications:' || auth.uid()::text\n  OR (\n    starts_with(realtime.topic(), 'group-chat-')\n    AND public.is_group_member(\n      NULLIF(replace(realtime.topic(), 'group-chat-', ''), '')::uuid,\n      auth.uid()\n    )\n  )\n  OR (\n    starts_with(realtime.topic(), 'presence-')\n    AND public.is_group_member(\n      NULLIF(replace(realtime.topic(), 'presence-', ''), '')::uuid,\n      auth.uid()\n    )\n  )\n);\n" },
  { name: "20260531185239_7d23989c-6633-487a-954f-117b548a5326.sql", sql: "\nREVOKE EXECUTE ON FUNCTION public.add_owner_as_group_member() FROM PUBLIC, anon, authenticated;\nREVOKE EXECUTE ON FUNCTION public.assign_default_role() FROM PUBLIC, anon, authenticated;\nREVOKE EXECUTE ON FUNCTION public.handle_new_user() FROM PUBLIC, anon, authenticated;\nREVOKE EXECUTE ON FUNCTION public.handle_new_user_email_preferences() FROM PUBLIC, anon, authenticated;\nREVOKE EXECUTE ON FUNCTION public.handle_new_user_trial() FROM PUBLIC, anon, authenticated;\nREVOKE EXECUTE ON FUNCTION public.send_welcome_email_on_signup() FROM PUBLIC, anon, authenticated;\nREVOKE EXECUTE ON FUNCTION public.update_article_feedback_counts() FROM PUBLIC, anon, authenticated;\nREVOKE EXECUTE ON FUNCTION public.update_deck_card_count() FROM PUBLIC, anon, authenticated;\nREVOKE EXECUTE ON FUNCTION public.update_group_member_count() FROM PUBLIC, anon, authenticated;\n" },
  { name: "20260605151105_70fa739c-d7ac-496e-91c0-ecf4d07dd5bc.sql", sql: "\nCREATE TABLE IF NOT EXISTS public.content_reports (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  reporter_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  content_type text NOT NULL,\n  content_id text,\n  reported_user_id uuid,\n  reason text NOT NULL,\n  details text,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\nGRANT SELECT, INSERT ON public.content_reports TO authenticated;\nGRANT ALL ON public.content_reports TO service_role;\nALTER TABLE public.content_reports ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \"users insert own reports\" ON public.content_reports\n  FOR INSERT TO authenticated WITH CHECK (reporter_id = auth.uid());\nCREATE POLICY \"users read own reports\" ON public.content_reports\n  FOR SELECT TO authenticated USING (reporter_id = auth.uid());\nCREATE POLICY \"admins read all reports\" ON public.content_reports\n  FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));\n\nCREATE TABLE IF NOT EXISTS public.user_blocks (\n  blocker_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  blocked_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (blocker_id, blocked_id)\n);\nGRANT SELECT, INSERT, DELETE ON public.user_blocks TO authenticated;\nGRANT ALL ON public.user_blocks TO service_role;\nALTER TABLE public.user_blocks ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \"users manage own blocks\" ON public.user_blocks\n  FOR ALL TO authenticated\n  USING (blocker_id = auth.uid())\n  WITH CHECK (blocker_id = auth.uid());\n" },
  { name: "20260605151938_d6c7c6fe-b2cb-4fd8-b7ca-c1f68be292b8.sql", sql: "CREATE OR REPLACE VIEW public.subscriptions_v\nWITH (security_invoker = true) AS\nSELECT\n  user_id,\n  plan,\n  status,\n  billing_interval AS interval,\n  current_period_end,\n  (status = 'trial') AS is_trial,\n  GREATEST(0, CEIL(EXTRACT(EPOCH FROM (trial_end_date - now())) / 86400))::int AS trial_days_remaining,\n  trial_end_date,\n  cancelled_at\nFROM public.subscriptions;\n\nGRANT SELECT ON public.subscriptions_v TO authenticated;" },
  { name: "20260606151336_a3bbb6ea-b0db-4f84-986a-2d4e67f73b80.sql", sql: "CREATE TABLE public.study_activity (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null,\n  material_id uuid references public.study_materials(id) on delete set null,\n  deck_id uuid references public.flashcard_decks(id) on delete set null,\n  activity_type text not null check (activity_type in\n    ('flashcard_review','quiz','notes_read','summary_read','concept_map','tutor_chat')),\n  duration_seconds integer not null default 0,\n  items_count integer not null default 0,\n  correct_count integer not null default 0,\n  xp_awarded integer not null default 0,\n  event_id uuid,\n  created_at timestamptz not null default now(),\n  unique (user_id, event_id)\n);\n\nGRANT SELECT, INSERT ON public.study_activity TO authenticated;\nGRANT ALL ON public.study_activity TO service_role;\n\nALTER TABLE public.study_activity ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Users view own activity\"\n  ON public.study_activity FOR SELECT\n  TO authenticated\n  USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users insert own activity\"\n  ON public.study_activity FOR INSERT\n  TO authenticated\n  WITH CHECK (auth.uid() = user_id);\n\nCREATE INDEX idx_study_activity_user_created\n  ON public.study_activity (user_id, created_at desc);\nCREATE INDEX idx_study_activity_user_type_created\n  ON public.study_activity (user_id, activity_type, created_at desc);\nCREATE INDEX idx_study_activity_user_material_type\n  ON public.study_activity (user_id, material_id, activity_type, created_at);\n\nCREATE VIEW public.study_activity_v\nWITH (security_invoker = true) AS\nSELECT\n  user_id,\n  created_at AS occurred_at,\n  duration_seconds,\n  items_count AS cards_or_items,\n  correct_count,\n  activity_type,\n  material_id\nFROM public.study_activity\nUNION ALL\nSELECT\n  user_id,\n  started_at AS occurred_at,\n  COALESCE(total_time_seconds, 0) AS duration_seconds,\n  COALESCE(cards_studied, 0) AS cards_or_items,\n  COALESCE(correct_count, 0) AS correct_count,\n  'flashcard_review'::text AS activity_type,\n  NULL::uuid AS material_id\nFROM public.study_sessions\nWHERE ended_at IS NOT NULL;\n\nGRANT SELECT ON public.study_activity_v TO authenticated;" },
  { name: "20260606151614_b90b6af7-8cfa-4547-a3f7-af0a1226d27a.sql", sql: "DO $$\nDECLARE\n  rec RECORD;\n  new_deck_id uuid;\n  inserted_count int;\nBEGIN\n  FOR rec IN\n    SELECT mf.user_id, mf.material_id, sm.title, sm.subject\n    FROM (\n      SELECT DISTINCT user_id, material_id FROM public.material_flashcards\n    ) mf\n    JOIN public.study_materials sm ON sm.id = mf.material_id\n    WHERE NOT EXISTS (\n      SELECT 1 FROM public.flashcard_decks d\n      WHERE d.source_material_id = mf.material_id\n        AND d.user_id = mf.user_id\n    )\n  LOOP\n    INSERT INTO public.flashcard_decks (name, user_id, description, subject, source_material_id, card_count)\n    VALUES (\n      COALESCE(rec.title, 'Untitled'),\n      rec.user_id,\n      'Auto-generated from \"' || COALESCE(rec.title, 'Untitled') || '\"',\n      rec.subject,\n      rec.material_id,\n      0\n    )\n    RETURNING id INTO new_deck_id;\n\n    INSERT INTO public.flashcards (deck_id, front, back, hint)\n    SELECT new_deck_id, front, back, hint\n    FROM public.material_flashcards\n    WHERE material_id = rec.material_id AND user_id = rec.user_id;\n\n    GET DIAGNOSTICS inserted_count = ROW_COUNT;\n\n    UPDATE public.flashcard_decks\n      SET card_count = inserted_count\n      WHERE id = new_deck_id;\n  END LOOP;\nEND $$;" },
];
